quests[29425] = { id = 29425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise vergleichen", description = "Passt auf, ich habe diesem zwielichtigen Kerl gesagt, dass es da einen Laden in der Gasse gibt, der seinen, ähm, Waren vielleicht offener gegenübersteht. \"Droffers und Sohn Bergungen\" ist der Name des Geschäfts.\n\nHaltet nach Dran Droffers Ausschau. Er überwacht die 'Bergung' von seltenen und wertvollen Gegenständen aus ganz Azeroth.", sourceObjective = "Begebt Euch zum Laden \"Droffers und Sohn Bergungen\" in der Gasse in Orgrimmar und sucht nach Hinweisen auf den Besuch des Kistendiebes.", progress = "Ihr seht aus, als wüsstet Ihr etwas über diese verschwundenen Waren.", completion = "Verlasst Euch auf Droffer, dass er direkt einen Käufer an der Hand hat. Wir sollten zusammen arbeiten, um diesen Dieb zu fassen und um zu verhindern, dass der Inhalt dieser Kiste in die falschen Hände fällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29426] = { id = 29426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtsmaßnahmen", description = "Es hat Euch also jemand anders angeheuert, um diese Kiste zu besorgen? Das hört sich für mich gar nicht gut an.\n\nDer Inhalt dieser Kiste gehört unter die Aufsicht der Archäologischen Akademie. Die in ihr enthaltenen Gegenstände sind sehr mächtig und sehr gefährlich.\n\nWir müssen zu dem Treffen gehen, dass Dran zwischen dem Dieb und dem Sammler vereinbart hat, aber zunächst müssen wir uns vor den Effekten schützen, die der Umgang mit der Kiste mit sich bringt.\n\nKauft etwas seltsamen Staub bei einem Verzauberkunsthändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln im Tal der Weisheit.", sourceObjective = "Besorgt Euch 2 Portionen seltsamen Staub, 5 Kristallphiolen und 5 Blutnesseln.", progress = "Habt Ihr alle Ingredienzien erhalten?", completion = "Dann wollen wir doch mal sehen, was aus den Alchemiestunden meiner Jugendzeit noch so hängengeblieben ist. Wenn es explodiert, habe ich etwas falsch gemacht.\n\nDieses Gebräu sollte uns vor den schlimmsten Auswirkungen, die das Tragen und die Handhabung der Kiste mit sich bringen, schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29427] = { id = 29427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Agent des Sammlers", description = "Dran zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in einer versteckten Ecke im Hof der Ruinen von Lordaeron treffen.\n\nSchnell, nehmt den Zeppelin nach Tirisfal!\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Wyvernschweif\" im Tal der Ehre, sobald Ihr die Kiste habt.", sourceObjective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Ruinen von Lordaeron.", progress = "Dies scheint die gesuchte Kiste zu sein.", completion = "Ranken aus dunkler Macht tanzen um die Kiste, aber es gibt keine Spur von Sanath Lim-yo. Ihr könnt die Kiste jetzt an Euch nehmen und zu Eurem Auftraggeber zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29428] = { id = 29428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was jetzt?", description = "Endlich habt Ihr die Kiste gefunden, die Edgar Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Repräsentanten der Archäologischen Akademie korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Delian Sonnenschatten geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?", sourceObjective = "Ihr könnt die Kiste entweder Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmars Tal der Stärke zurückbringen.\n\n-ODER-\n\nIhr könnt die Kiste Delian Sonnenschatten im \"Wyvernschweif\" in Orgrimmars Tal der Ehre übergeben.", progress = "Habt Ihr die Kiste wie besprochen dabei?", completion = "Ah, Ihr habt es also geschafft, die Kiste zu bekommen, bevor Erzmagier Xylems Mann sie aus der Stadt schaffen konnte. Exzellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[29429] = { id = 29429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unheimliche Kiste", description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch." }
quests[29430] = { id = 29430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Wisst Ihr, ich habe Anson noch gar nicht hier draußen gesehen.\n\nIn letzter Zeit verbringt er seine ganze Zeit damit, sich in der \"Güldenen Rose\" volllaufen zu lassen.\n\nEtwas muss ihm wirklich an die Nieren gehen! Würdet Ihr vielleicht mal nach ihm sehen?", sourceObjective = "Besucht Anson Hastings in der \"Güldenen Rose\" in Sturmwinds Handelsdistrikt.", completion = "Was wollt Ihr?\n\nIch werde meine Studien niemals abschließen, {race}. Die Forschungsarbeit meines Lebens und jetzt ist der Kurier mit den Reagenzien, die ich für die Experimente brauche, spät dran!", sourceObjectiveStatus = "unverified-source-field" }
quests[29431] = { id = 29431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Mit meinem Freund Edgar ist etwas nicht in Ordnung. Normalerweise liebt er die Festivitäten rund um die Schlotternächte.\n\nEr verbringt seine ganze Zeit damit, in der Kneipe \"Zum Gebrochenen Hauer\" in Orgrimmar mit den Orcs zu trinken. Wäret Ihr so gut und würdet mal bei ihm vorbeischauen und nachsehen, ob es irgendwas gibt, womit man ihn aufmuntern könnte?", sourceObjective = "Sprecht mit Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmar.", completion = "Was wollt Ihr?\n\nCandace hat Euch geschickt? Sie kennt mich einfach zu gut. Ich bin in meinen Studien an dem klassischen Punkt der Betriebsblindheit angekommen und warte auf eine sehr wichtige Lieferung, aber der Kurier will und will nicht kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29432] = { id = 29432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegierung", description = "Meine Pflicht bindet mich, Euren Aussagen unverzüglich nachzugehen, {race}, was bedeutet, dass meine Mission hier nun in Eure Hände fällt.\n\nEin Anstieg uralter Magie, viel zu stark, um natürlichen Ursprungs zu sein, führte mich hierher. Seitdem habe ich eine zutiefst beunruhigende Entwicklung entdeckt.\n\nEin Ast wurde von Nordrassil abgebrochen und tief in die Feuerlande verschleppt. Dort droht ein mächtiges Ritual, Nordrassil zu verderben und ihn in Flammen aufzuzehren.\n\nIhr müsst einen Weg finden, das Ritual zu unterbrechen und den Zweig des Weltenbaumes zurückzuholen.", sourceObjective = "Erlangt den Zweig von Nordrassil aus den Feuerlanden zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[29433] = { id = 29433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Eure Stärke", description = "Einige Leute haben so lange Spaß, bis jemand verletzt wird. Ich nenne solche Leute Schwächlinge.\n\nWahre Stärke beweist nur der, der jemanden oder etwas verletzt. Ihr verletzt Euch selbst, weil Ihr Euren Körper an seine Grenzen führt, und Ihr verletzt die, die anderen schaden wollen.\n\nWenn Ihr der Stärkste sein wollt, müsst Ihr kämpfen. Wie wichtig ist Euch das?\n\nIch will, dass Ihr die niederstreckt, die Euch herausfordern und mir einen Beweis Eures Triumphs bringt.", sourceObjective = "Kerri Hicks möchte, dass Ihr 250 grausige Trophäen erbeutet. Um sie zu bekommen, müsst Ihr Wesen töten, die Euch Erfahrung oder Ehre gewähren und den Abenteuerführer des Dunkelmond-Jahrmarkts bei Euch tragen.", progress = "Ohne Fleiß kein Preis.", completion = "Habt Ihr Euch Herausforderungen gesucht oder einfach nur Eber auf einem Feld abgeschlachtet?\n\nIch bin aus gutem Grund die Stärkste.\n\nVielleicht werde ich Euch eines Tages zeigen, wie stark ich wirklich bin, {class}. Bis dahin müsst Ihr Euch weiter anstrengen, aber vergesst nicht, ab und zu eine Pause zu machen.\n\nSo wie jetzt zum Beispiel. Hier, genießt den Dunkelmond-Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29434] = { id = 29434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzergeneral", description = "Willkommen zu unserem bescheidenen kleinen Dampfpanzerkampf-Simulator! Für nur einen Spieljeton könnt Ihr Euer strategisches Können unter Beweis stellen. Fahrt über unseren Parcours und zerstört die Panzerziele.", sourceObjective = "Zerstört mit Eurem Dunkelmond-Panzer 30 Ziele in der veranschlagten Zeit.", completion = "Eine beeindruckende Demonstration!\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29436] = { id = 29436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die menschliche Kanonenkugel", description = "Für nur einen Spieljeton des Dunkelmond-Jahrmarkts könnt Ihr Euch aus der Blastenheimer 5000 Ultrakanone abschießen lassen. Doch damit ist der Spaß noch nicht vorbei! Wir haben ein Ziel im Meer nahe des Piers aufgebaut.\n\nWenn Ihr bei Euren Landungen fünf Punkte erzielt, könnt Ihr Gewinnlose bekommen.\n\nEin Treffer ins Schwarze bringt 5 Punkte, einer ins Ziel 3 Punkte und einer knapp neben dem Ziel 1 Punkt.\n\nViel Glück bei der Landung!", sourceObjective = "Erreicht 5 Kanonenzielpunkte, indem Ihr in der Nähe des Kanonenziels landet.", progress = "Hals und Beinbruch!", completion = "5 Punkte? Gut gemacht! Hier sind Eure Lose.\n\nViel Spaß auf dem Rest des Dunkelmond-Jahrmarkts!", sourceObjectiveStatus = "unverified-source-field" }
quests[29437] = { id = 29437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Wächter", description = "Fandral Hirschhaupt ist hier auf dem Hyjal gefangen gehalten worden. Es war der grüne Drache Alysra - eine von uns! -, die damit beauftragt war, Fandral zu bewachen.\n\nWir können nur vermuten, dass es dem Schattenhammer gelungen ist, sie zu verderben. Ihr müsst sie stellen, {name}. Vernichtet sie, wenn es sein muss - ich kann es nicht ertragen, dabei zuzusehen.\n\nZuletzt wurde sie bei den Ruinen von Lar'donir gesichtet, westlich des Weltenbaums.", sourceObjective = "Stellt und tötet Alysra bei den Ruinen von Lar'donir.", sourceObjectiveStatus = "unverified-source-field" }
quests[29438] = { id = 29438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er schießt, er trifft!", description = "Glaubt Ihr, dass Ihr gut schießen könnt? Habt Ihr eine ruhige Hand?\n\nWie wäre es dann mit ein paar Schüssen?\n\nEs kostet Euch nur einen Spieljeton, Eure Fähigkeiten unter Beweis zu stellen.\n\nNa, wie gut seid Ihr?", sourceObjective = "Erreicht 25 Punkte in 60 Sekunden.", progress = "Ein stehendes Ziel zu treffen, ist nicht so einfach, wie es aussieht.", completion = "Ich wusste, dass Ihr das schafft, {class}. Hier ist Euer Preis. Genießt den Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29439] = { id = 29439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Weltenschamanen", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, {name}.\n\nAls ein Mitglied der Allianz weiß ich, dass Ihr möglicherweise Bedenken hegt, mit dem, den Ihr Thrall nennt, dem früheren Kriegshäuptling der Horde, zusammenzuarbeiten. Aber er hat explizit darum gebeten, dass es ein Held der Allianz ist, der ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nLasst Eure Zweifel beiseite, {class}, und antwortet dem Ruf des Weltenschamanen.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", sourceObjective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", completion = "Es scheint, als wäre meine Nachricht in Sturmwind angekommen.\n\nIch danke Euch, {name}. Dann wollen wir uns mal an die Arbeit machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29440] = { id = 29440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Weltenschamanen", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, {name}.\n\nThrall hat sein Amt als Kriegshäuptling der Horde niedergelegt, aber für seine neue Aufgabe benötigt er die Unterstützung seines Volkes mehr als je zuvor. Er hat darum gebeten, dass einer der besten Streiter der Horde ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", sourceObjective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", completion = "Es scheint, als wäre meine Nachricht in Orgrimmar angekommen.\n\nIch danke Euch, {name}. Dann wollen wir uns mal an die Arbeit machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29441] = { id = 29441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Bauch der Bestie" }
quests[29443] = { id = 29443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger Kristall", description = "Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.\n\nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.", sourceObjective = "Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr den her?\n\nSolche Kristalle sind sehr selten, viele Sammler suchen danach. Ich würde diesen gern untersuchen und auf dem Jahrmarkt ausstellen. Würdet Ihr ihn gegen eine großzügige Anzahl von Losen des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29444] = { id = 29444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein exotisches Ei", description = "Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.\n\nBringt das Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt.", sourceObjective = "Bringt das monströse Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr dieses Ei gefunden? Darin verbirgt sich sicherlich etwas Monströses und Wunderbares. Ein sehr passender Neuzugang für unseren Zoo. Würdet Ihr Euch davon für eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts trennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29445] = { id = 29445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Zauberfoliant", description = "Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten gnollischen Jahrmarktswahrsager auf dem Dunkelmond-Jahrmarkt, von Interesse sein.", sourceObjective = "Bringt den geheimnisvollen Zauberfolianten zu Sayge auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Ein seltsamer Zauberfoliant, wie interessant! So einen habe ich noch nie gesehen. Ich hätte ihn sehr gern für meine Sammlung. Würdet Ihr ihn gegen Lose des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29446] = { id = 29446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wundersame Waffe", description = "Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Einige winzige Scharten weisen darauf hin, dass sie auch im Kampf benutzt wurde.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt, daher würde sich Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt bestimmt für dieses Stück interessieren.", sourceObjective = "Bringt die verzierte Waffe zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr eine solch wundervolle Klinge gefunden?\n\nWas für eine Verarbeitung! Das ist wahrlich eine Waffe, mit der sich jeder Held schmücken könnte. Ich würde sie sehr gern ausstellen.\n\nWürdet Ihr eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29447] = { id = 29447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger Kristall", description = "Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.\n\nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.", sourceObjective = "Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29448] = { id = 29448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein exotisches Ei", description = "Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.\n\nBringt das Ei zu Yebb Nabetand nahe der Tierunterkünfte, wenn der Jahrmarkt geöffnet ist.", sourceObjective = "Bringt das monströse Ei zu Yebb Nabetand, wenn der Dunkelmond-Jahrmarkt geöffnet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29449] = { id = 29449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Zauberfoliant", description = "Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten Jahrmarktswahrsager, von Interesse sein. Ihr findet ihn in der Nähe seines Zeltes auf der Dunkelmond-Insel.", sourceObjective = "Bringt den geheimnisvollen Zauberfolianten zu Sayge, wenn der Dunkelmond-Jahrmarkt geöffnet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29450] = { id = 29450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wundensame Waffe", description = "Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Aber sie wurde nicht nur zur Zierde getragen, sondern auch im Kampf benutzt, das beweisen die winzigen Scharten auf der Klinge.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt. Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für dieses Stück interessieren.", sourceObjective = "Bringt die verzierte Waffe zu Professor Thaddeus Paleo, wenn der Dunkelmond-Jahrmarkt geöffnet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29451] = { id = 29451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterstratege", description = "Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren.", sourceObjective = "Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Das sieht nach einem sehr seltenen Buch aus…", completion = "Ich weiß nicht, wie Ihr daran gekommen seid und ich bin klug genug, nicht zu fragen. Würdet Ihr Euch für Lose des Dunkelmond-Jahrmarkts davon trennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29452] = { id = 29452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Zeit ist gekommen", description = "<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>\n\n<Junger/Junge:c> {class}, seid ganz ruhig und hört meine Worte.\n\nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.\n\nFindet mich in Orgrimmar, sterbliches Wesen, denn Eure Zeit ist gekommen.", sourceObjective = "Sprecht mit Ziradormi in Orgrimmar.", completion = "Lasst uns beginnen, sterbliches Wesen.\n\nWir haben keine Zeit zu verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29453] = { id = 29453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Zeit ist gekommen", description = "<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>\n\n<Junger/Junge:c> {class}, seid ganz ruhig und hört meine Worte.\n\nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.\n\nFindet mich in Sturmwind, sterbliches Wesen, denn Eure Zeit ist gekommen.", sourceObjective = "Sprecht mit Coridormi in Sturmwind.", completion = "Lasst uns beginnen, sterbliches Wesen.\n\nWir haben keine Zeit zu verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29454] = { id = 29454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterstratege", description = "Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren. Sucht ihn in der Heimat des Jahrmarkts auf der Dunkelmond-Insel auf.", sourceObjective = "Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29455] = { id = 29455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft den Ring", description = "Hey Ihr! Haltet ein!\n\nWollt Ihr allen beweisen, wie talentiert Ihr seid? Sorgt dafür, dass drei Ringe auf der Dunkelmond-Schildkröte landen, dann bekommt Ihr eine Belohnung.\n\nFür einen Spieljeton könnt Ihr einen Stapel Ringe kaufen, um der Welt zu zeigen, warum wir Euch auf dem Jahrmarkt {name}, \"<den Adleräugigen/die Adleräugige>\" nennen.", sourceObjective = "Werft 3 Ringe auf die Dunkelmond-Schildkröte.", progress = "Geht's dem Wurfarm gut?", completion = "Ich wusste, dass Ihr das könnt, {class}. Gebt uns die restlichen Ringe, falls welche übrig sind, dann bekommt Ihr Euer Gewinnlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[29456] = { id = 29456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erbeutetes Banner", description = "Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert. Zeigt ihm das Banner, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Was für ein wundervolles Banner! Das hätte ich gerne in meiner Sammlung.\n\nWürdet Ihr es mir für einige Lose des Dunkelmond-Jahrmarkts überlassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29457] = { id = 29457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Insigne des Feindes", description = "Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.\n\nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt. Zeigt ihm das Abzeichen, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal aufsucht.", sourceObjective = "Bringt das eroberte Insigne zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Das ist ein bemerkenswert gut erhaltenes Offiziersinsigne. Viele Offiziere besuchen zwar den Jahrmarkt, aber keiner von ihnen will sich von seinen Abzeichen trennen. Würdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29458] = { id = 29458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erbeutete Tagebuch", description = "Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers handelt, der sehr von sich und seinen Abenteuern eingenommen ist.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.", sourceObjective = "Bringt das Tagebuch eines Abenteurers zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Ein bemerkenswerter Fund!\n\n<Der Professor blättert in dem Buch.>\n\nEinige Seiten sind kaum noch lesbar, aber wenn auch nur ein Drittel des Inhalts der Wahrheit entspricht, handelt es sich um einen wahren Schatz. Würdet Ihr es gegen eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29459] = { id = 29459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erbeutetes Banner", description = "Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert.", sourceObjective = "Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29460] = { id = 29460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Insigne des Feindes", description = "Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.\n\nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt.", sourceObjective = "Bringt das eroberte Insigne zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29461] = { id = 29461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erbeutete Tagebuch", description = "Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers der Horde handelt, der sehr von sich und seinen Abenteuern eingenommen ist.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.", sourceObjective = "Bringt das erbeutete Tagebuch zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29463] = { id = 29463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hau-den-Gnoll", description = "Wollt Ihr ein paar Gnolle hauen? Dann seid Ihr am richtigen Ort.\n\nEure Aufgabe ist einfach: Erreicht 30 Punkte in einer Minute.\n\nBenutzt den Holzhammer, den ich Euch geben werde und legt los. Sprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Erreicht 30 Punkte beim Gnollhauen.", progress = "Wie habt Ihr Euch geschlagen?", completion = "Ihr habt die Gnolle also besiegt. Fühlte sich gut an, oder?\n\nHier ist Euer Preis. Genießt den Rest des Dunkelmond-Jahrmarkts!", sourceObjectiveStatus = "unverified-source-field" }
quests[29464] = { id = 29464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge der Weissagung", description = "Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.\n\nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr diese Runensammlung her? So eine habe ich seit Jahren nicht mehr gesehen. Es wird mir eine Freude sein, ihr Rätsel zu entschlüsseln!\n\nWürdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29465] = { id = 29465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge der Weissagung", description = "Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.\n\nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29466] = { id = 29466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele fette Frösche", description = "Fast jeder in Azeroth hat schon von unseren weltberühmten Knusperfröschen gehört. Wir können kaum die Nachfrage danach erfüllen!\n\nIhr seht aus, als wüsstet Ihr, wie man eine Angel hält, {race}. Würdet Ihr mir helfen, meine Froschvorräte aufzufüllen?\n\nDie leckersten Knusperfrösche bekommt man, wenn man die fetten verwendet, die nahe des Steinbullensees vorkommen. Keine Sorge, es wird sich für Euch lohnen.", sourceObjective = "Fangt 5 fette Frösche nahe des Steinbullensees.", sourceObjectiveStatus = "unverified-source-field" }
quests[29467] = { id = 29467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerreparatur", description = "Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.\n\nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.", sourceObjective = "Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29468] = { id = 29468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby braucht zwei Paar Schuhe", description = "Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.\n\nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.\n\nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?", sourceObjective = "Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29469] = { id = 29469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", sourceObjective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29470] = { id = 29470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerbt meine Häute", description = "Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.\n\nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.", sourceObjective = "Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[29471] = { id = 29471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Zukunft", description = "Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.\n\nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.\n\nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Ich werde Euch dafür belohnen.", sourceObjective = "Stellt aus dem Bund exotischer Kräuterprophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29472] = { id = 29472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begehrte Preise", description = "Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.\n\nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch ein Set geben. Ihr werdet einige Teile bei einem Gemischtwarenhändler wie Shadi Nebelläufer auf der zentralen Anhöhe von Donnerfels erwerben müssen, aber sie sind nicht teuer.\n\nWollt Ihr mir helfen?", sourceObjective = "Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29473] = { id = 29473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kratzer, Beulen, blaue Flecke", description = "Die Arbeit auf dem Dunkelmond-Jahrmarkt ist gefährlich, {name}. Unsere Arbeiter verletzen sich oft beim Aufbau, Abbau und Transport der Attraktionen.\n\nWir schicken die am schwersten verletzten Arbeiter auf die Anhöhe der Geister in Donnerfels, aber viele der leicht verletzten können auch hier behandelt werden. Warum nehmt Ihr nicht diese Bandagen und seht, ob Ihr den verletzten Arbeitern helfen könnt?", sourceObjective = "Nehmt die Bandagen des Dunkelmond-Jahrmarkts und heilt damit 4 verletzte Schausteller.", sourceObjectiveStatus = "unverified-source-field" }
quests[29474] = { id = 29474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Abfall kann nützlich sein", description = "Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, {name}. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.\n\nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?", sourceObjective = "Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29475] = { id = 29475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kenne die Geheimnisse der Gobliningenieurskunst.\n\nIhr seht aus, als würdet Ihr gern Dinge in die Luft jagen, aber ich benötige Proben Eurer Arbeit. Bringt mir zwanzig große Eisenbomben, zwanzig Stangen robustes Dynamit und fünf explodierende Schafe.\n\nWenn Ihr diese Gegenstände zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt bringt, wird er Euch offiziell zum Gobliningenieur mit Zugang zu allen Bauplänen ernennen!", sourceObjective = "Bringt 20 große Eisenbomben, 20 Stangen robustes Dynamit und 5 explodierende Schafe zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", progress = "Überlasst mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung, dann werde ich Euch das Wissen vermitteln, das Ihr benötigt, um Mitglied im exklusiven Club der Gobliningenieure zu werden.", completion = "Anscheinend seid Ihr tatsächlich bereit für eine richtige Ausbildung. Hiermit ernenne ich Euch zum Gobliningenieur, {name}!\n\nIhr könnt Euch die teuflischen Erfindungen aller Gobliningenieure ansehen. Genießt es und versucht, Euch nicht in die Luft zu sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29476] = { id = 29476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Wenn Ihr wirklich einmalige Gegenstände herstellen wollt, dann seid Ihr am richtigen Ort. Ich sehe zwar schon, dass Ihr ein geübter Ingenieur seid, aber ich benötige einige Proben Eurer Arbeit. Ich möchte Euer Können richtig einschätzen, damit ich Euch für die Zukunft besser in gnomorientierten Techniken unterrichten kann. Bringt mir folgende Proben: Sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.\n\nÜberlasst mir diese Gegenstände, dann ernenne ich Euch offiziell zum Gnomeningenieur mit Zugang zu allen Bauplänen.Ihr erlernt:", sourceObjective = "Bringt 6 Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen zu Glotz Widrikus in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29477] = { id = 29477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kann Euch die Gnomeningenieurskunst beibringen.\n\nIhr scheint zwar zu wissen, was Ihr tut, aber ich benötige einige Proben Eurer Arbeit. Bringt mir sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.\n\nSobald Ihr diese Gegenstände bei einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt abgebt, seid Ihr offiziell ein Gnomeningenieur und erhaltet Zugriff auf alle Baupläne!", sourceObjective = "Bringt 6 Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", progress = "Sobald Ihr mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung unterbreitet habt, könnt Ihr ein zertifizierter Gnomeningenieur werden. Dann erhaltet Ihr uneingeschränkten Zugriff auf alle Baupläne der Gnomeningenieure.", completion = "Am heutigen Tag wird aus Euch ein echter Ingenieur, {name}. Macht Euch keine Gedanken mehr über diese schmutzigen Bomben und Sprengstoffe, denn Ihr werdet bald über Euch selbst hinauswachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29478] = { id = 29478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine prickelnde Mischung", description = "Als <Alchemist/Alchemistin> habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?\n\nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.\n\nGalissa Sonnentau wird Euch genügend Saft für Eure Kreation verkaufen können.", sourceObjective = "Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.", sourceObjectiveStatus = "unverified-source-field" }
quests[29479] = { id = 29479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilkräuter", description = "Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.\n\nMit ihnen kann man Wunden behandeln und Essen würzen.\n\nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?", sourceObjective = "Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29480] = { id = 29480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner, überall Banner!", description = "Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.\n\nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf der zentralen Anhöhe von Donnerfels.\n\nDie Gegenstände, die Ihr sonst noch benötigt, könnt Ihr bei Shadi Nebelläufer auf der zentralen Anhöhe von Donnerfels erwerben.", sourceObjective = "Stellt mit Hilfe des Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf der zentralen Anhöhe von Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[29481] = { id = 29481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.\n\nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Tränke und Transmutation nicht mehr angeboten.", sourceObjective = "Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer.", progress = "Habt Ihr die Fläschchen?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[29482] = { id = 29482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Eisen zu Gold, Wasser zu Feuer... ich kann Euch helfen, wenn Ihr ein Meister der Transmutation werden wollt.\n\nDie Ausbildung ist sehr teuer, also müsst Ihr mir einige der besten transmutierten Materialien der Welt bringen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Transmutationsbeherrschung abgeschlossen habt, werden Euch Tränke und Elixiere nicht länger angeboten.", sourceObjective = "Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr die Materialien?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[29483] = { id = 29483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarkt der Eitelkeiten", description = "Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.\n\nSeid Ihr geübt im Juwelenschleifen und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?\n\nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen fürs Juwelenschleifen bearbeitet werden, entstehen daraus wunderschöne Edelsteine.", sourceObjective = "Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde \"Edelsteine\".", sourceObjectiveStatus = "unverified-source-field" }
quests[29484] = { id = 29484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Frosch knusprig wird", description = "Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!\n\nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?\n\nBei Shadi Nebelläufer auf der zentralen Anhöhe von Donnerfels könnt Ihr Mehl kaufen. Darin wälzt Ihr die Frösche, dann kocht Ihr sie in dem Topf hinter mir.", sourceObjective = "Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29485] = { id = 29485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß für die Kleinen", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sand hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", sourceObjective = "Bringt 15 Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29506] = { id = 29506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine prickelnde Mischung", description = "Als <Alchemist/Alchemistin> habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?\n\nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.\n\nEin Gastwirt im Wald von Elwynn oder in Mulgore wird Euch genügend Saft für Eure Kreation verkaufen können.", sourceObjective = "Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.", progress = "Was macht der Mondbeerenfizz?", completion = "Eure Kreation sieht vielversprechend aus. Mit ein wenig Glück werden wir bald ein neues Lieblingsgetränk haben!\n\nIch danke Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29507] = { id = 29507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß für die Kleinen", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", sourceObjective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", progress = "Wie sieht es aus? Wollt Ihr ein paar Fossilienfragmente spenden?", completion = "Großartig! Die Kinder werden sich sehr freuen, wenn sie diese Teile \"entdecken\".", sourceObjectiveStatus = "unverified-source-field" }
quests[29508] = { id = 29508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby braucht zwei Paar Schuhe", description = "Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.\n\nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.\n\nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?", sourceObjective = "Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.", progress = "Wie geht's dem alten Mädchen?", completion = "Danke für Eure Hilfe, {name}! Hier ist die versprochene Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29509] = { id = 29509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Frosch knusprig wird", description = "Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!\n\nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?\n\nDas Mehl, in dem Ihr die Frösche wälzen müsst, bekommt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore.", sourceObjective = "Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.", progress = "Rieche ich etwa frische Knusperfrösche?", completion = "Die sind auf den Punkt gebraten, {name}. Sehr gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29510] = { id = 29510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Abfall kann nützlich sein", description = "Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, {name}. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.\n\nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?", sourceObjective = "Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.", progress = "Habt Ihr etwas Wahrsagerstaub bekommen?", completion = "Das hilft mir schon mal weiter. Wenn Ihr noch einmal helfen wollt, besucht einfach den alten Sayge, wenn der Dunkelmond-Jahrmarkt in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29511] = { id = 29511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerreparatur", description = "Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.\n\nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.", sourceObjective = "Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.", completion = "Sehr gute Arbeit. Die Panzer laufen wieder. Hier sind die versprochenen Lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29513] = { id = 29513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerer Fisch im Schlafrock", description = "Wir haben gerade ein neues Gericht in unsere Speisekarte aufgenommen, den Fisch im Schlafrock. Es ist so beliebt, dass wir die Nachfrage kaum erfüllen können!\n\nIhr seht aus, als wüsstet Ihr, wie man mit einer Angel umgeht, {race}. Würdet Ihr mir bei der Aufstockung meiner Vorräte helfen?\n\nWir wollen doch all die Jahrmarktsbesucher, die etwas Neues ausprobieren wollen, nicht enttäuschen, oder?", sourceObjective = "Fangt 5 große Meeresheringe im Ozean rund um die Dunkelmond-Insel.", progress = "Habt Ihr die Fische?", completion = "Genau die richtigen! Hier sind wie versprochen Eure Lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29514] = { id = 29514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilkräuter", description = "Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.\n\nMit ihnen kann man Wunden behandeln und Essen würzen.\n\nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?", sourceObjective = "Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.", progress = "Wie geht das Kräutersammeln voran?", completion = "Danke, {name}. Sobald der Dunkelmond-Jahrmarkt wieder in der Stadt ist, würde ich gern noch einmal auf Eure Hilfe zurückgreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29515] = { id = 29515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Zukunft", description = "Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.\n\nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.\n\nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Das Pergament, das Ihr dafür braucht, könnt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben.", sourceObjective = "Stellt aus dem Bund exotischer Kräuterprophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.", progress = "Habt Ihr die Horoskope geschrieben?", completion = "Die sehen genau wie meine aus. Ihr habt ein gutes Gespür für Details. Ich danke Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29516] = { id = 29516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarkt der Eitelkeiten", description = "Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.\n\nSeid Ihr geübt in Juwelierskunst und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?\n\nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen für Juwelierskunst bearbeitet werden, entstehen daraus wunderschöne Edelsteine.", sourceObjective = "Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde \"Edelsteine\".", progress = "Ist es Euch gelungen, Ersatzedelsteine für den Schmuck unserer Künstler zu schleifen?", completion = "Sehr gute Arbeit, {name}. Ihr seid wirklich talentiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29517] = { id = 29517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begehrte Preise", description = "Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.\n\nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch gern ein Set geben. Ihr werdet einige Teile bei einem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben müssen, aber sie sind nicht teuer.\n\nWollt Ihr mir helfen?", sourceObjective = "Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.", progress = "Habt Ihr die Preise hergestellt?", completion = "Sehr gute Arbeit! Die Preise sehen genauso aus wie die anderen. Ich danke Euch für Eure Hilfe.\n\nWenn Ihr noch einmal helfen wollt, dann sucht mich auf, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29518] = { id = 29518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", sourceObjective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", progress = "Habt Ihr Schrott gefunden? Der Platz ist voll davon.", completion = "Das ist eine Menge Schrott. Ich danke Euch für Eure Hilfe. Damit werde ich viele Panzer reparieren können.\n\nHier, nehmt dies als kleine Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29519] = { id = 29519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerbt meine Häute", description = "Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.\n\nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.", sourceObjective = "Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.", progress = "Die Arbeit auf dem Dunkelmond-Jahrmarkt hört nie auf.", completion = "Ich danke Euch für Eure Hilfe, {name}. Ich werde Euch in guter Erinnerung behalten.\n\nUnd wenn Ihr möchtet, könnt Ihr mir gern wieder helfen, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29520] = { id = 29520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner, überall Banner!", description = "Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.\n\nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf dem Lagerplatz des Jahrmarkts.\n\nEs fehlen noch einige Teile, doch die solltet Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben können.", sourceObjective = "Stellt mit einem groben Faden sowie rotem und blauem Farbstoff zusammen mit dem Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf dem Lagerplatz des Jahrmarkts.", progress = "Habt Ihr einen guten Platz für Euer neues Banner gefunden?", completion = "Danke für Eure Hilfe. Ihr seid recht begabt mit Nadel und Faden. Wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist, könnt Ihr uns gern wieder helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29521] = { id = 29521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Singenden Teiche", description = "Es ist von höchster Wichtigkeit, dass wir die drei verbleibenden Geister ebenfalls unversehrt zurückbringen. Ich bin zu alt, um dies selbst zu bewerkstelligen, und Aysa und Ji sind trotz ihrer Stärken zu engstirnig, was ihre Ideale betrifft.\n\nIhr besitzt alle Qualitäten <eines Helden/einer Heldin> und zusätzlich eine Ausgewogenheit, über die sie nicht verfügen. Ihr seid <derjenige, der/diejenige> die; diese Aufgabe erfüllen muss.\n\nShu, der Geist des Wassers, befindet sich irgendwo in den Singenden Teichen östlich von hier. Sucht dort Aysa auf und arbeitet mit ihr zusammen, um ihn zu finden. Wir alle verlassen uns auf Euch.", sourceObjective = "Sprecht mit Aysa Wolkensänger bei den Singenden Teichen.", completion = "Es ist schön, Euch wiederzusehen, {name}.\n\nDas hier ist der Teich des Stinktiers, wie Ihr sicherlich bemerkt habt.\n\nSeit der Entstehung von Shen-zin Su sind über die Jahre hinweg Tiere in einigen dieser magischen Teiche verendet. Durch ihren Tod wurden die Gewässer von ihrem Geist durchdrungen und jeder, der das Wasser berührt, wird ihre Gestalt annehmen.\n\nEs gibt einige verfluchte Teiche hier, von denen manche gefährlicher sind als andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[29522] = { id = 29522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ji, Anhänger der Huojin", description = "Ein weiterer meiner talentiertesten Schüler wartet in Wu-Song im Nordwesten auf Euch. Ihr werdet feststellen, dass er in vielerlei Hinsicht anders denkt und handelt als Aysa, aber durch ihre Unterschiede bringen sie sich gegenseitig ins Gleichgewicht.\n\nJi Feuerpfote wird Euch beim Sammeln der Opfergaben für den Geist des Feuers anleiten. Vertraut auf seine Weisheit.", sourceObjective = "Sprecht mit Ji Feuerpfote in Wu-Song.", completion = "Seid gegrüßt! Ihr seht selbstsicher und zuversichtlich aus… Das gefällt mir!\n\nIch habe einige recht beeindruckende Gerüchte über Euch gehört. Wenn Ihr nur halb so fähig seid, wie man sagt… Ich habe das Gefühl, dass wir gute Freunde sein werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[29523] = { id = 29523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen schüren", description = "Das Eigenartige am Wind ist, dass es durchaus schwer sein kann, ihn in die Finger zu bekommen.\n\nMeiner Meinung nach ist die beste Methode, eine Art lebendigen Wind zu finden. Wenn er mir eine verpassen kann, dann kann ich auch ihm eine verpassen und er wird mir nicht einfach davonwehen.\n\nMacht Euch auf den Weg zum Schrein der Sommerbrise im Süden und beschwört mit diesem Windstein einen solchen lebendigen Wind. Bezwingt ihn, entnehmt ihm eine flatternde Brise und kehrt zu mir zurück, damit wir entscheiden können, wie der nächste Schritt aussehen wird.", sourceObjective = "Beschafft eine flatternde Brise.", progress = "Wenn sich eine Gelegenheit ergibt, ist es unsere Pflicht, sie zu ergreifen. Eine Entscheidung im Nachhinein zu bezweifeln ist genauso viel wert, wie gleich aufzugeben.", completion = "Ihr wisst, was es heißt, eine Gelegenheit beim Schopfe zu packen. Ich denke, dass wir beide aus demselben Holz geschnitzt sind, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29524] = { id = 29524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des unterdrückten Stolzes", description = "Es ist etwas ganz anderes, einem lebenden Gegner anstatt dieser Übungsziele im Hof gegenüberzustehen. Lebende Gegner schlagen zurück. Eine sehr reelle Angst vor dem Versagen - und manchmal sogar dem Tod - überkommt Euch.\n\nIhr müsst den Mut aufbringen, diese Ängste zu überwinden.\n\nFordert die anderen Schüler innerhalb des Tempels oder auf den Stufen davor heraus und bezwingt sie.", sourceObjective = "Bezwingt 6 Huojin- oder Tushui-Schüler.", completion = "Faszinierend, mein junger Schüler.\n\nDie meisten der anderen Schüler haben schon einige Zeit hier verbracht, aber Ihr seid schon jetzt in der Lage, Euch mit ihnen zu messen.\n\nDas spricht für Euch, aber es gibt noch weitere Lektionen, die ich Euch gerne lernen sehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[29527] = { id = 29527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg im Bollwerk", description = "Wachhabender Gargolmar und Vazruden der Herold haben das Kommando über die Verteidigung des Bollwerks.\n\nWenn Ihr sie ausschaltet, werden die Soldaten in Panik geraten.\n\nTötet sie und bringt mir einen Beweis für Eure Tat, damit die Invasion beginnen kann!", sourceObjective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Steingardist Stok'ton.", progress = "Diese Mission hängt von Eurem Erfolg ab, {name}.", completion = "Ohne ihre Anführer sollten die Truppen in Panik geraten.\n\nAber es geht hier um mehr als die Beseitigung einiger Wachen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29528] = { id = 29528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg im Bollwerk", description = "Die Verteidigung der Höllenfeuerzitadelle hängt in erster Linie vom Bollwerk ab, das als eine Art Frühwarnsystem dient.\n\nBeseitigt Wachhabenden Gargolmar und Vazruden den Herold. Ohne sie wird die Eroberung des Bollwerks ein Kinderspiel sein.", sourceObjective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Vorhutsspäher Chadwick.", progress = "Wart Ihr erfolgreich? Von dieser Mission hängt sehr viel ab, {name}.", completion = "Ich wusste, dass ich auf Euch zählen kann!\n\nIhre Streitkräfte sind nun führerlos. Die Invasion kann beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29529] = { id = 29529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Zitadelle", description = "Einer unserer Späher berichtet, er habe irgendwo im Bollwerk einen Agenten der Brennenden Legion gesehen. Wenn das stimmt, laufen wir Gefahr, dass die Ehrenfeste von zwei Seiten angegriffen wird!\n\nWenn Ihr diesen Teufel findet, dann bringt ihn um.", sourceObjective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Vorhutsspäher Chadwick.", progress = "Habt Ihr dort drinnen Dämonen entdeckt?", completion = "Dann ist es also wahr. Die Höllenorcs und die Brennende Legion arbeiten auf irgendeine Weise zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29530] = { id = 29530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Zitadelle", description = "Einer unserer Späher hat unangenehme Neuigkeiten überbracht. Wir haben einen mächtigen Agenten der Brennenden Legion im Bollwerk entdeckt!\n\nBringt diesen Dämon um, bevor er seinen Vorgesetzten von unseren Plänen berichten kann.", sourceObjective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Steingardist Stok'ton.", progress = "Konntet Ihr die üble Kreatur beseitigen?", completion = "Gut gemacht. Wir brauchen die Zeit, die Ihr uns erkauft habt, um der Verbindung zwischen Höllenorcs und brennender Legion nachzugehen. Eure Taten haben vielleicht Hunderten das Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29531] = { id = 29531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Stuff" }
quests[29532] = { id = 29532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiobsbotschaft", description = "Als Ihr die Leiche von Vazruden dem Herold untersucht, entdeckt Ihr einen Brief, dessen Siegel ungebrochen ist. Ein reich verziertes \"I\" ist in dem blutroten Wachs zu sehen. Ihr öffnet das Siegel und lest die verstörende Nachricht.\n\nVorhutsspäher Chadwick wird sie sich bestimmt ansehen wollen!", sourceObjective = "Bringt den unheilvollen Brief zu Vorhutsspäher Chadwick.", sourceObjectiveStatus = "unverified-source-field" }
quests[29533] = { id = 29533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiobsbotschaft", description = "Als Ihr die Leiche von Vazruden dem Herold untersucht, entdeckt Ihr einen Brief, dessen Siegel ungebrochen ist. Ein reich verziertes \"I\" ist in dem blutroten Wachs zu sehen. Ihr öffnet das Siegel und lest die verstörende Nachricht.\n\nSteingardist Stok'ton wird sie sich bestimmt ansehen wollen!", sourceObjective = "Bringt den unheilvollen Brief zu Steingardist Stok'ton.", sourceObjectiveStatus = "unverified-source-field" }
quests[29534] = { id = 29534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collect Things" }
quests[29535] = { id = 29535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie bluten!", description = "Der Schöpfer erzeugt neue Höllenorcs, indem er ihnen Dämonenblut injiziert.\n\nMeine Vorgesetzten glauben, dass sich der Prozess rückgängig machen lässt, aber um das auszuprobieren, benötigen wir Proben ihres Blutes und die Injektionsspritze des Schöpfers.", sourceObjective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Caza'rez.", progress = "Ihr seid zurück und sogar lebendig! Gut gemacht. Besser als alle anderen bis jetzt.", completion = "Diese Phiolen könnten das Ende der Höllenorcs einläuten. Ich hoffe, dass Ihr versteht, wie wichtig das für unseren Feldzug wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[29536] = { id = 29536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Zorns", description = "Wir wissen, dass die Höllenorcs ihren Fokus erhöhen, indem sie Orcs Dämonenblut injizieren.\n\nBegebt Euch tief in diese unheiligen Hallen und findet heraus, was dort geschieht. Wir können es erst riskieren, eine Armee hineinzuschicken, wenn wir genau wissen, was uns erwartet.", sourceObjective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Caza'rez.", completion = "<Ihr erzählt Caza'rez alles, was Ihr im Blutkessel gesehen habt.>\n\nWenn sie das den braunen Orcs der Mag'har antun können, dann sind auch wir in Gefahr! Wir müssen vorsichtig sein, sonst werden alle in Thrallmar zu hirnlosen Bestien.", sourceObjectiveStatus = "unverified-source-field" }
quests[29537] = { id = 29537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht, Lücke!", description = "Im ganzen Blutkessel gibt es nur ein Gebiet, das unsere Seher trotz aller Mühen nicht erreichen können.\n\nDiese \"Lücke\", wie sie es nennen, ist recht groß. Dort wird bestimmt Magtheridon gefangen gehalten.\n\nIhr müsst die Ursache dieser Störungen finden und vernichten.", sourceObjective = "Tötet Keli'dan den Zerstörer und kehrt zu Caza'rez zurück.", progress = "Ja, was ist?", completion = "Die Störungen haben nachgelassen, aber wir können das Gebiet immer noch nicht sehen. Wir werden der Sache weiter nachgehen. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29538] = { id = 29538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie bluten!", description = "Mit Dämonenblut und einer speziellen Spritze verwandelt der Schöpfer braune und grüne Orcs in rote. Wir würden uns das Blut gern ansehen und damit herumspielen, bis es Orcs aller Farben in harmlose, friedliche Ochsen verwandelt.\n\nBringt mir einige Proben ihres Blutes, damit wir anfangen können. Und vergesst die Spritze nicht!", sourceObjective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Gunny.", progress = "Habt Ihr das Blut, Prinzessin? Wir haben Euch bestimmt nicht darum gebeten, weil es unwichtig ist.", completion = "Verdammt beeindruckend! Damit steigt Ihr auf Platz acht meiner Lieblingspersonen in den qualmenden Ruinen dieses bemitleidenswerten Planeten auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[29539] = { id = 29539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Zorns", description = "Hat sich gezeigt, dass die Eierköpfe in der Ehrenfeste nicht viel von diesem Ort hier sehen können. Lügende, faule Magier sind das, nichts weiter.\n\nWie dem auch sei, wir wissen nicht genau, was hier vorgeht. Also werdet Ihr das herausfinden!", sourceObjective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Gunny.", completion = "<Ihr erzählt Gunny alles, was Ihr im Blutkessel gesehen habt.>\n\nIhr habt doch auch Beute für den alten Gunny, oder?\n\nNein, Ihr habt natürlich recht. Ich schulde Euch eine Belohnung für Eure harte Arbeit, auch wenn Ihr ohne mich überhaupt nicht hineingegangen wäret.", sourceObjectiveStatus = "unverified-source-field" }
quests[29540] = { id = 29540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zerstörer", description = "Die verstecken hier irgendwo so einen großen, alten Dämon, hab ich gehört. Und da gibt's auch einen Orc, der darauf achten soll, dass er bleibt, wo er hingehört.\n\nEin Orc ist ein Orc, und Orcs werden umgebracht, richtig? Ist egal, was er tut oder getan hat, einer weniger schadet nie.", sourceObjective = "Tötet Keli'dan den Zerstörer und kehrt zu Gunny zurück.", completion = "Wirklich? Ihr wollt eine Belohnung, weil Ihr einen Orc umgebracht habt? So wie in Ruhm und Reichtum und edle Reittiere?\n\nZu meiner Zeit war es Belohnung genug, einen Orc töten zu DÜRFEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[29541] = { id = 29541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Care of It" }
quests[29542] = { id = 29542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Zitadelle", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden Thrallmar überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf den Weg nach Westen zum Höllenfeuerbollwerk und sprecht mit Steingardist Stok'ton. Die Geheimmission, die er leitet, wird der Horde den Weg in die Zitadelle ebnen.", sourceObjective = "Sprecht mit Steingardist Stok'ton im Höllenfeuerbollwerk.", completion = "Schädelbrecher ist nicht gerade freundlich, aber er weiß, was er tut. Und für Euch gibt es auch genug Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29543] = { id = 29543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Zitadelle", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden die Ehrenfeste in Kürze überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf nach Westen zum Höllenfeuerbollwerk und sprecht dort mit Vorhutsspäher Chadwick. Die Mission, die er leitet, wird der Allianz den Weg in die Zitadelle ebnen.", sourceObjective = "Sprecht mit Vorhutsspäher Chadwick im Höllenfeuerbollwerk.", completion = "Altumus ist wirklich ein Juwel. Aber wir werden hier nur lebend herauskommen, wenn wir im Bollwerk siegreich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29544] = { id = 29544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutkessel", description = "Caza'rez erwartet Euch im Blutkessel. Er hat bereits einen kleinen Bereich gesäubert und unsere Seher versuchen gerade herauszufinden, was dort unten vorgeht.\n\nIch befürchte jedoch, dass das nicht reichen wird. Caza'rez könnte ein oder zwei robuste Klingen sicherlich gut gebrauchen. Geht zu ihm und unterstützt ihn bei der Beseitigung der Höllenorcs.", sourceObjective = "Sprecht mit Caza'rez im Blutkessel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29545] = { id = 29545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutkessel", description = "Dieser Krieg ist längst noch nicht vorbei. Wir müssen dafür sorgen, dass die Front der Höllenorcs nicht mehr durch neue Rekruten verstärkt wird. Nur dann können wir siegen.\n\nBegebt Euch in den Blutkessel und sprecht mit Gunny. Er hat einen kleinen Bereich darin gesichert und könnte bestimmt Eure Hilfe gebrauchen. Aber seid gewarnt. Gunny ist... ungewöhnlich.", sourceObjective = "Sprecht mit Gunny im Blutkessel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29546] = { id = 29546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zünglein an der Waage", description = "Diese vermaledeiten eingeborenen Affenwilden greifen uns seit dem Tag an, an dem wir einen Fuß an Land gesetzt haben!\n\nWir haben uns wacker gehalten, bis sie die Hälfte unserer Leute entführt haben - einschließlich des Admirals.\n\nSchaut Euch nur an, wie viele sie sind! Es nimmt einfach kein Ende und wir pfeifen auf dem letzten Loch.\n\nWenn Ihr hier seid, um uns aus diesem Schlamassel herauszuhelfen, dann schafft einige der Affen aus der Welt.\n\nSie oder wir, {race}!", sourceObjective = "Tötet 12 Ho-zen-Verwüster.", sourceObjectiveStatus = "unverified-source-field" }
quests[29547] = { id = 29547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Königs", description = "Seid gegrüßt, {class}.\n\nIch wurde beauftragt, eine Gruppe für eine Mission von höchster Wichtigkeit zusammenzustellen.\n\nBitte eilt sofort in die Burg Sturmwind für eine Besprechung mit König Varian Wrynn. Ich werde im Kriegsraum des Königs auf Euch warten.", sourceObjective = "Sucht Großadmiralin Jes-Tereth im Kriegsraum von Burg Sturmwind in Sturmwind auf.", completion = "Unsere Rolle ist äußerst wichtig. Admiral Taylor und sein Flaggschiff sind verschwunden. Was noch wichtiger ist: Der junge Prinz war bei ihm und unser primäres Ziel besteht darin, ihn sicher zurück nach Hause zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29548] = { id = 29548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mission", description = "Nun denn, Ihr habt den König gehört. Admiral Taylors letzte Übertragung kam von irgendwo im südlichen Meer.\n\nWir werden umgehend mit der Luftaufklärung beginnen. Der Prinz – der Weiße Bauer – ist dabei die oberste Priorität.\n\nDie Himmelsfeuer ist vollgetankt, beladen und zum Aufbruch bereit. Sie wartet mit ihrer Mannschaft am Himmel nördlich des Hafens.\n\nTrefft Eure letzten Vorbereitungen und meldet Euch dann bei Himmelsadmiralin Rogers auf dem Deck. Wir werden ohne weitere Verzögerungen aufbrechen.", sourceObjective = "Meldet Euch bei Admiralin Rogers auf der Himmelsfeuer.", completion = "Das da unten ist eine komplette Basis der Horde! Wo waren unsere Aufklärer!?\n\nNun denn, {class}, es wird Zeit herauszufinden, wozu dieses aufgerüstete Luftschiff in der Lage ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29549] = { id = 29549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugmeister vom Himmel geholt", description = "Ich habe eine Bestandsaufnahme der Vermissten gemacht. Unter ihnen befindet sich Donovar Murall, unser Flugmeister.\n\nEr ist nicht nur ein wichtiger Bestandteil unserer Mannschaft, er ist auch ein guter Freund.\n\nBitte findet ihn und bringt ihn lebend zurück.", sourceObjective = "Sprecht mit Donovar Murall im Viridianhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[29550] = { id = 29550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneeschwinges Rettung", description = "<Als Donovar Euch sieht, bricht er in Tränen aus.>\n\nD-d-die verfluchten Affenrandalierer h-h-haben mich in die Wälder hier gezerrt. Ich dachte, mit mir wär's vorbei, aber dann kam meine treue Schneeschwinge mir zu Hilfe!\n\nSie hat sie in die Flucht geschlagen, doch dann haben sie sich alle auf sie gestürzt! Un' mit all den Affen in der Gegend is' sie...\n\n<Donovar putzt sich lautstark die Nase.>\n\n...is' sie geliefert! Buhuuhuuuuuu! Es sei denn...\n\nHört mal, {class}, ich hab' hier überall in den Wäldern Ingwerblatt wachsen sehen. Ich flehe Euch an, bringt mir etwas von dem Heilkraut und Schneeschwinge könnte es vielleicht doch schaffen!", sourceObjective = "Sammelt 4 Ingwerblätter für Schneeschwinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[29551] = { id = 29551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hainpirscher", description = "Wir versuchen immer noch, uns einen Überblick über die nach dem Kampf übriggebliebene Mannschaft zu verschaffen.\n\nIch fürchte, dass viele in den Wäldern festsitzen. Sie sind möglicherweise verwundet und kämpfen ums nackte Überleben.\n\nWir wissen, dass der Wald im Norden voller wilder Tiger ist.\n\nGeht und säubert die Wälder von ihnen. Damit verschafft Ihr vielen unserer Männer und Frauen die Chance, es lebend zurückzuschaffen.", sourceObjective = "Tötet 8 Hainpirscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29552] = { id = 29552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In kritischem Zustand", description = "Die erste Schlacht haben wir zwar gewonnen, es gibt aber noch eine äußerst wichtige Aufgabe.\n\nIn der ersten Luftschlacht wurden Dutzende Himmelsfeuerpiloten abgeschossen.\n\nOhne medizinische Hilfe wird sich ihr Zustand im Lauf der Zeit verschlechtern, bis sie schließlich sterben. Wir sind ihre einzige Überlebenshoffnung.\n\nBegebt Euch in den Obstgarten und belebt alle Piloten wieder, die Ihr findet.\n\nWir werden niemanden zurücklassen.", sourceObjective = "Belebt 6 verwundete Piloten im Hain von Pel'zin wieder. Ihr könnt auch Heilzauber oder Bandagen verwenden, um sie wiederzubeleben.", completion = "Gut gemacht, {name}. Dank Eurer Anstrengungen können diese Soldaten wieder in den Kampf ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29553] = { id = 29553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Admiral", description = "Also gut. Die Hinweise, die Ihr gefunden habt, deuten darauf hin, dass es Anduins Schiff mit Admiral Taylor als Kapitän war. \n\nUnd laut Admiral Taylors letztem Eintrag wollte er die Ho-zen abwehren und das Schiff nach dem Schiffbruch schützen.\n\nDie Einheimischen behaupten, die Ho-zen würden manchmal Gefangene nehmen, und ich habe Taylors Leichnam zwischen den Wrackteilen nicht gefunden. Taylor ist also wahrscheinlich im Lager der Ho-zen im Nordosten.\n\nBrecht auf, wir haben keine Zeit zu verlieren!", sourceObjective = "Findet Admiral Taylor.", completion = "<Ihr habt ihn gefunden, aber der Admiral ist bewusstlos. Er scheint dem Tode näher als dem Leben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29554] = { id = 29554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkener Schrott", description = "He, {name}!\n\nDie Küste hier ist mit Bruchstücken von Werkzeugen und Metall des Schiffswracks übersät.\n\nNun mag jeder andere glauben, dass es sich dabei um Plunder handelt, aber ich bin sicher, dass ich das meiste davon noch verwenden kann. Ich habe einmal ein U-Boot nur mit einem Bronzerohr und einem Luffaschwamm repariert!\n\nBesorgt mir einige Stücke des durchnässten Schrotts, der entlang der Küste in der Nähe des Schiffs liegt. Ich brauche sie für mein nächstes Projekt.", sourceObjective = "Sammelt 8 Teile durchnässten Schrott.", sourceObjectiveStatus = "unverified-source-field" }
quests[29555] = { id = 29555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weiße Bauer", description = "Also, <Soldat/Soldatin>. Ich habe eine entscheidende Mission für Euch.\n\nBegebt Euch zur Küste südlich von hier – in der Bucht dort werdet Ihr das Wrack eines Schiffs der Allianz finden. Ich möchte, dass Ihr es durchsucht und herausfindet, ob Anduin Passagier darauf war.\n\nBergt dann das Logbuch des Kapitäns und sucht darin nach Hinweisen darauf, wo wir ihn finden können.\n\nDa es sich um das Logbuch eines Militärschiffes handelt, wird es in Code verfasst sein. Bringt es anschließend zu Nick Codeknack. Er bewacht das Wrack am anderen Ende der Bucht.", sourceObjective = "Durchsucht das Wrack der Herold im Jadewald nach Hinweisen auf seine Ladung und bergt das verschlüsselte Logbuch des Kapitäns.", progress = "Nun?", completion = "Schön... zeigt her... der Code vom Zeitpunkt des Verschwindens des Schiffs...\n\n<Nick rechnet offenbar in seinem Kopf.>\n\nAha!", sourceObjectiveStatus = "unverified-source-field" }
quests[29556] = { id = 29556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ho-zen sind nicht Freund, sondern Feind", description = "Wir haben ein Wrack der Allianz im Süden geortet. Den Einheimischen dort zufolge wird es jedoch derzeit von einer Gruppe dieser \"Ho-zen\" genannten Geschöpfe geplündert.\n\nDass sie unsere Schiffswracks ausnehmen, beweist bereits, dass sie uns nicht freundlich gesinnt sind. Wir können nicht zulassen, dass sie in unseren Schiffen auf Beutezug gehen, unseren Nachschub stehlen und – schlimmer noch – womöglich Überlebende gefangen nehmen oder gar töten.\n\nAuf mit Euch, erledigt sie! Wenn Ihr damit fertig seid, meldet Euch bei Nick Codeknack, unserem SI:7-Agent in der Gegend.", sourceObjective = "Tötet 10 Ho-zen beim Wrack der Herold.", completion = "Gute Arbeit. Solche Dreckskerle – uns zu treten, wenn wir am Boden liegen...\n\nDas wird sie lehren, nicht noch einmal ein Schiff der Allianz zu plündern!", sourceObjectiveStatus = "unverified-source-field" }
quests[29557] = { id = 29557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mission geht weiter", description = "Das Flaggschiff des Königs ist nicht weit von hier auf Grund gelaufen.\n\nOffenbar hat das Schiff kurz nach der Landung Anduins sichere Ankunft signalisiert, aber als sie Truppen entsandt haben, um ihn zu finden, war er bereits verschwunden.\n\nIch möchte das Wrack nach Hinweisen durchsuchen.\n\nNick und Sully sind bereits vor Ort an der Unglücksstelle. Geht den Strand entlang nach Osten und seht, ob sie Hilfe benötigen.", sourceObjective = "Sprecht mit Nick am Saphirende im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[29558] = { id = 29558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegspfad", description = "Ich merke, dass Ihr Euren Freund retten wollt. Ich kann Euch helfen, wenn Ihr mir ebenfalls helft.\n\nZunächst einmal ist es wohl offensichtlich, dass eine Flucht viel leichter zu bewerkstelligen sein wird, wenn hier weniger Schlingschwänze umherstreifen.\n\nTötet die Wachen der Ho-zen um uns herum und wir sind der Freiheit schon einen Schritt näher.", sourceObjective = "Tötet 12 Kronenhüpfer oder Schlammseher der Schlingschwänze.", progress = "Ihr kämpft gut, Fremder.", completion = "Ahahaha! Ihr seid tapfer.\n\nEine bewundernswerte Eigenschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29559] = { id = 29559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Brüder befreien", description = "Ihr mögt ein Außenstehender sein, doch wir haben in den Ho-zen einen gemeinsamen Feind.\n\nViele Mitglieder meines Stammes sind in Käfigen in der Nähe eingesperrt. Ich habe außerdem Eure... Allianzsoldaten gesehen.\n\nIch kann nicht fortgehen, ohne meine Brüder befreit zu haben - so, wie Ihr Eure Kameraden nicht zurücklassen könnt.\n\nDie Schlingschwänze sind im Besitz der Schlüssel zu diesen Käfigen. Findet die Schlüssel und befreit unsere Freunde.", sourceObjective = "Befreit 6 Jinyu- oder Allianzgefangene.", completion = "Ihr habt meine Brüder befreit? Gut.\n\nWir stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[29560] = { id = 29560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Macht", description = "Die Schädel der Ho-zen sind begehrte Objekte in meinem Dorf.\n\nWir verwenden sie, um Riten zu zelebrieren. Je älter der Schädel, desto mächtiger ist seine Magie.\n\nZu unserem Glück sind die Ho-zen nachlässig, die schmutzigen Biester. Sie lassen die Schädel ihrer Verstorbenen überall zwischen ihren Hütten und Lagerfeuern herumliegen.\n\nSammelt diese Schädel für mich und ich werde Euch fürstlich belohnen.", sourceObjective = "Sammelt 8 uralte Ho-zen-Schädel.", progress = "Diese Schädel sind für meinen Stamm sehr wertvoll. Wie viele habt Ihr eingesammelt?", completion = "Es ist gut zu sehen, dass Ihr so einfallsreich seid, {name}. Diese Eigenschaft wird von meinem Volk bewundert.\n\nDiese wunderbaren Exemplare, die Ihr mir gebracht habt, werden mächtige Magie hervorbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29561] = { id = 29561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allen Widrigkeiten zum Trotz", description = "Wir beide sind die einzigen Missionsagenten, die es zum Basislager geschafft haben, {class}.\n\nIch habe gesehen, wie die anderen vom SI:7 über dem Wald im Norden ihre Schleudersitze betätigten.\n\nIhr solltet schleunigst dorthin gehen und alle Überlebenden retten.", sourceObjective = "Findet die vermissten SI:7-Agenten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29562] = { id = 29562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Gefängnis", description = "Ohne Heilung wird Euer Freund Taylor sterben. Mein Dorf befindet sich im Osten von hier, mitten in dem großen See.\n\nIch werde Taylor selbst dorthin tragen, doch die Kämpfe in dieser Richtung sind höchst gefährlich.\n\nIch brauche Eure Hilfe, um mir einen Weg durch die Ho-zen zu bahnen, damit ich sicher zu meinem Dorf laufen kann.\n\nSchafft Ihr das?", sourceObjective = "Tötet 10 Entbeiner der Schlingschwänze.", completion = "Danke, {name}. Dank Euch haben wir es sicher hierher geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29563] = { id = 29563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen im Kampf", description = "Ihr müsst mir helfen! Wir wurden ausgesandt, um die verschiedenen Bereiche des Kessels zu erkunden, aber das war vor einiger Zeit und meine Freunde sind noch nicht zurückgekehrt.\n\nBitte findet heraus, ob ihnen etwas zugestoßen ist. Naturalist Biss und Jäter Gründaum sind in diese Richtung gegangen.", sourceObjective = "Findet heraus, was Naturalist Biss und Jäter Gründaum zugestoßen ist. Kehrt dann zu Behüterin Jhang zurück.", completion = "Der Verlust des Lebens... so schmerzhaft.\n\n<Behüterin Jhang seufzt.>\n\nDanke, {name}. Wenn wir alle wieder vereint sind, werden uns die Naga nichts anhaben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29564] = { id = 29564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der betrogene Bruder", description = "Anfangs gelang es meinem Dorf, den Angriffen der Naga auszuweichen. Wir hätten es bis nach Nagrand geschafft, wenn mein Bruder nicht gewesen wäre. Mit unseren Seelen erkaufte er sich seine Freiheit.\n\nNun arbeitet er hier als Sklavenaufseher und peitscht seine eigenen Brüder aus, bis ihre Rücken bluten. Dafür muss Mennu bezahlen, {race}.", sourceObjective = "Tötet Mennu den Verräter und kehrt zu Nahuud zurück.", completion = "Mennus Tod kann die Wunden meiner Familie und Freunde nicht heilen, aber wenigstens können sie den Rest ihres Lebens in Freiheit verbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29565] = { id = 29565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Pudels Kern", description = "Nahuud hat mir erklärt, zwei mächtige Wesen, Rokmar der Zerquetscher und Quagmirran, seien als erste von den Naga nach deren Ankunft versklavt worden. Sie haben bei der Unterwerfung vieler Völker in den Zangarmarschen geholfen.\n\nIch tue das sehr ungern, aber ich muss Euch bitten, sie zu töten.", sourceObjective = "Bringt die Klaue des Eindringlings und das Auge des Sklaventreibers zu Behüterin Jhang.", progress = "Habt Ihr sie getötet?", completion = "Ich bin froh, dass ihr Geist nun frei ist. Ich wünschte, das gleiche könnte man von den anderen ihrer Art sagen.\n\nEs gibt noch viel zu tun, vor allem in den anderen Teilen des Echsenkessels.", sourceObjectiveStatus = "unverified-source-field" }
quests[29566] = { id = 29566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Expedition", description = "Die Sümpfe sind wunderschön, findet Ihr nicht? Abgesehen natürlich von den Naga, die das Wasser abpumpen.\n\nIch habe eine kleine Expedition zum Echsenkessel geschickt. Sie sollte die Naga beobachten, aber bis jetzt ist niemand zurückgekehrt. Ich mache mir Sorgen um sie.\n\nWürdet Ihr Euch zu den Sklavenunterkünften unterhalb des Schlangensees begeben und nach Behüterin Jhang suchen?", sourceObjective = "Sprecht mit Behüterin Jhang in den Sklavenunterkünften.", completion = "Was macht Ihr denn hier unten? Ihr könnt doch sehen, dass es hier nicht gerade sicher ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[29567] = { id = 29567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Mutter", description = "Die Fungusgiganten greifen zwar heutzutage mein Volk an, aber die Marschenläufer haben bereits mehr Unschuldige auf dem Gewissen als alle anderen Kreaturen, die ich kenne. Sie sind seit Urzeiten unser Feind.\n\nIhre Brutmutter, die man auch Schattenmutter nennt, lebt in den Tiefen dieses Sumpfes. Wenn es Euch gelingen sollte, sie zu vernichten und mir ihr Gehirn als Beweis zu bringen, würde ich noch meinen Enkeln von Eurer ruhmreichen Tat erzählen.", sourceObjective = "Bringt das Gehirn der Schattenmutter zu T'shu.", progress = "Ihr seid zurück. Heißt das die Schattenmutter ist nicht mehr?", completion = "Die Schattenmutter ist tot! Normalerweise schwelge ich ja nicht in solchen Gemetzeln, aber der Schmerz, den die große Mutter und ihre Brut über Jahrhunderte meinem Volk zugefügt haben, ist unaussprechlich.\n\nIch bin Euch auf ewig dankbar, mutiger {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29568] = { id = 29568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein notwendiges Übel", description = "Hungarfenn und Quagmirran herrschten einst gemeinsam über die Fungusgiganten. Seit Quagmirrans Tod lastet diese Verantwortung allein auf Hungarfenns Ranken.\n\nWir müssen den Riesen töten, bevor er versklavt und als Waffe gegen uns eingesetzt werden kann.", sourceObjective = "Tötet Hungarfenn und kehrt zu Naturalist Biss zurück.", completion = "Ihr habt den Zangarmarschen an diesem Tag einen großen Gefallen erwiesen, {name}. Die Fungusgiganten sind zwar von Natur aus angriffslustig, aber sie sind ein wichtiger Teil des Ökosystems.", sourceObjectiveStatus = "unverified-source-field" }
quests[29569] = { id = 29569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Kalithreshs wichtigster Besitz", description = "Kriegsherr Kalithresh benutzt den Tiefensumpf als eine Art Brutkammer für Gha'zan, eine mächtige Hydra, die er auf die Zangarmarschen loslassen will, sobald sie ausgewachsen ist.\n\nIch befürchte, dass sich die Naga nicht mehr aufhalten lassen werden, wenn die Bestie ihre endgültige Größe erreicht hat. Findet Gha'zan und tötet sie zu unserem Schutz.", sourceObjective = "Tötet Gha'zan und bringt ihre Schuppe zu Behüterin Jhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[29570] = { id = 29570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Expedition", description = "Die restlichen Mitglieder meiner Expedition sind irgendwo hier drinnen. Wir brauchen das Wissen, das sie erlangt haben, und die Fähigkeiten, die sie besitzen, sonst werden wir die Naga niemals schlagen.\n\nSucht nach Erdbinder Rayge und Windrufer Klaue und stellt sicher, dass es ihnen gut geht.", sourceObjective = "Findet heraus, was mit Erdbinder Rayge und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang zurück.", progress = "Konntet Ihr die beiden finden? Geht es ihnen gut?", completion = "Bald werden wir wieder vereint sein, und das habe ich Euch zu verdanken!\n\nWir werden die Naga schneller besiegen, als Ihr denkt. Sie haben keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[29571] = { id = 29571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Wildnis", description = "Der Irdene Ring arbeitet oft eng mit dem Zirkel des Cenarius zusammen. So ist es auch dieses Mal.\n\nReist nach Norden zum Tiefensumpf und sprecht mit Behüterin Jhang. Sie leitet eine Expedition in den Echsenkessel, um die Naga aufzuhalten und die Zangarmarschen zu retten.", sourceObjective = "Sprecht mit Behüterin Jhang im Tiefensumpf.", completion = "Der Tiefensumpf steht kurz davor, zu einem Teil des Systems zu werden, das die Naga im Echsenkessel etabliert haben. Ihr müsst uns helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29572] = { id = 29572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Shaffars Astrale haben uns ganz aus der Managruft ausgeschlossen. Zum Glück habe ich einen Plan. Auch wenn wir nicht durch die Eingangstür können, bin ich mir sicher, dass es innen viele Transporter gibt.\n\nIch möchte, dass Ihr zuerst den Weg für meine Gruppe freiräumt und dann einen der Transporter aktiviert, damit wir hineinteleportieren können.\n\nAktiviert den Transporter in der Kammer genau vor Shaffars Kammern, wenn Ihr den Weg freigemacht habt. Keine Sorge, ich werde Euch dafür entlohnen...", sourceObjective = "Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.\n\nWenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammer und aktiviert ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29573] = { id = 29573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Es ist hier jetzt fast so sicher, dass meine Leute kommen und sich holen können, was rechtmäßig ihnen gehört. Die einzig große, noch verbleibende Gefahr stellt Shaffars Leibgarde dar. Von der wimmelt es hier.\n\nKümmert Euch um diese Streitkräfte, während ich wieder zu Kräften komme.", sourceObjective = "Tötet 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder. Kehrt danach zu Konstrukteur Morphalius zurück.", completion = "Wunderbar! Haramad wird sich über die guten Neuigkeiten freuen! Dieser Ort wird ihm wie ein reifer Apfel in die Hand fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29574] = { id = 29574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätselhafte Wesen", description = "Nahe des Eingangs dieser Hallen gibt es eine Kreatur, die Pandemonius genannt wird. Sie ist in der Lage, die Energien der Leere so zu verändern, dass sie sich daraus versorgen und stärken kann.\n\nWeiter hinten liegt Tavarok, ein Wesen, das die gleiche Energie in eine kristalline Struktur umwandelt, die stärker ist als alles, was ich je gesehen habe!\n\nIch brauche dringend Proben für weitere Untersuchungen.", sourceObjective = "Bringt Pandemonius' Essenz und Tavaroks Herz zu Mamdy dem Ologen.", progress = "Wenn Ihr nicht habt, wonach ich suche, verschwendet Ihr nur meine Zeit.", completion = "Diese Proben sind äußerst interessant. Sie werden mir sehr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29575] = { id = 29575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Konkurrenz untergraben", description = "Dank der Barriere, die Nexusprinz Shaffar errichtet und der Truppen, die er aufgestellt hat, kann er diese Gruft in aller Seelenruhe ausplündern.\n\nNexusprinz Haramad ist darüber nicht gerade begeistert. Deshalb hat er einen sehr ansehnlichen Preis auf Shaffars Kopf ausgesetzt.", sourceObjective = "Bringt Shaffars Bandagen zu Konstrukteur Morphalius.", progress = "Hattet Ihr Euch für den Preis auf Shaffars Kopf interessiert?", completion = "Ich hätte nicht gedacht, dass ein {race} einen Nexusprinzen besiegen kann. Ihr habt mich überrascht und Euch diese schöne Belohnung mehr als verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[29576] = { id = 29576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch von Sorge", description = "Mein Augenlicht ist schon lange verblasst, doch wenn der Wind richtig steht, kann ich immer noch die Blüten des Obstgartens Nektarhauch riechen, als ob ich sie in meinen Händen halte.\n\nHeute ist ihr Duft allerdings mit Rauch vermengt. Wenn Ihr Euch dazu in der Lage seht, schaut doch bitte im Obstgarten nach dem Rechten. Vielleicht spielt mir meine alte Nase einfach einen Streich.\n\nIhr findet den Obstgarten im Südwesten, jenseits der Statue der Jadeschlange.", sourceObjective = "Sprecht mit Shao dem Widerspenstigen im Obstgarten Nektarhauch.", completion = "Wenn Ihr hergekommen seid, um Euch mit meinen Fäusten zu unterhalten, stellt Euch hinten an. Ansonsten könnte ich Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29577] = { id = 29577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashyos Vision", description = "Seht Euch das mal an!\n\n<Ashyo zeigt zum mächtigen Wasserfall im Norden.>\n\nDas muss wohl die Wasserzufuhr für das gesamte Tal sein!\n\nDenkt mal darüber nach, {name}: Die Pandaren pflanzen mit diesem Wasser Gemüse an, das so groß ist wie ein Haus. Wie ist das möglich? Was ist das Geheimnis?\n\nDie Alten meines Volkes kennen eine Methode, um mit dem Wasser zu sprechen und die Zukunft vorherzusagen. Vielleicht gewährt die gleiche Technik auch Einblicke in den Ursprung dieses Gewässers...\n\nEs wäre zumindest einen Versuch wert!", sourceObjective = "Sprecht mit Ashyo bei den Teichen der Reinheit und beobachtet sein Ritual.", progress = "Was hat dieser Jinyu dort drüben vor?", completion = "Ich kann kaum glauben, dass er das mit einem Stock sehen konnte... Vielleicht steckt doch mehr hinter den \"verrückten Jinyuritualen\" als wir dachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29578] = { id = 29578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstand", description = "Die verfluchten Mogu sind wie aus dem Nichts über uns hergefallen! Wen sie nicht sofort töten, den zerren sie fort in die Wälder.\n\nDas hier ist der einzige sichere Unterschlupf, und ich kann nichts anderes tun, als die Tür zuzuhalten.\n\nWas sagt Ihr? Seid Ihr willens, für die Schwachen einzustehen und für sie zu kämpfen?", sourceObjective = "Tötet 8 Gormaliplünderer und 8 Gormaliverbrenner im Obstgarten Nektarhauch.", completion = "Gute Arbeit. Doch es gibt noch mehr zu tun, wenn wir dieses Dorf retten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29579] = { id = 29579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammelt die Überlebenden", description = "Die Einwohner dieses Dorfes sind einfache Bauern - keine Kämpfer wie Ihr und ich. Dennoch verteidigen sie hartnäckig ihr Zuhause so gut sie eben können.\n\nDurchsucht das Dorf nach allen, die noch aufrecht stehen können und sagt ihnen, sie sollen sich hier bei Hanae versammeln.", sourceObjective = "Sprecht mit 5 Bauern von Nektarhauch in der Umgebung vom Obstgarten Nektarhauch und schickt sie zum sicheren Unterschlupf.", progress = "Bitte sagt mir, dass es Überlebende gibt...", completion = "Sie sind drinnen. Aufgewühlt, aber dank Euch lebendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[29580] = { id = 29580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geräte aus dem Obstgarten", description = "Sie mögen keine Waffenmeister sein, doch viele dieser Bauern können eine einfache Hacke oder einen Rechen schwingen, um ihrem Willen Ausdruck zu verleihen.\n\nDiese Meisterschaft in Verbindung mit der richtigen Motivation kann eine Armee auf die Beine stellen, die in der Lage ist, den Mogu die Stirn zu bieten.\n\nWenn Ihr einige Werkzeuge aus dem Obstgarten herholt, werde ich sie an die Kampfwilligen verteilen.", sourceObjective = "Bergt 6 Obstgartenwerkzeuge aus dem Obstgarten Nektarhauch.", progress = "Waren noch Werkzeuge da?", completion = "Unter uns gibt es niemanden wie Euch, {class}, doch wir werden kämpfen und die, die wir lieben, beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29581] = { id = 29581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der goldene Traum", description = "Ashyo muss das erlebt haben, was wir den goldenen Traum nennen.\n\nViele von uns, die hier arbeiten, haben ihn auch gesehen - häufig nach einem langen Arbeitstag in den Teichen. Man sagt, diese Vision - und das Hochgefühl, das sie bringt - sei eine Belohnung des Geistes für die Nutzung des Körpers.\n\nEs gibt jedoch auch eine einfachere Methode, die wir allerdings kaum noch nutzen: Man kann einen Tee aus Lotuswurzeln und Traumlaub, das in der Nähe des Schreins im oberen Bereich zu finden ist, herstellen.\n\nBringt das Traumlaub in das Dorf zu Yan - er wird Euch den Tee zubereiten.", sourceObjective = "Bringt einen Traumlaubzweig zu Yan in Neu-Cifera.", progress = "Ja, braucht Ihr etwas?", completion = "Ah... Traumlaub! Ihr wollt also den goldenen Traum sehen, nicht wahr?\n\nWenn ich jetzt so darüber nachdenke, fällt mir auf, dass ich den Traum seit Jahren nicht mehr geträumt habe - zuletzt in meinen jungen Jahren beim stundenlangen Spielen in den Teichen. Lange bevor ich mich den kulinarischen Künsten widmete.\n\nWie es aussieht, habt Ihr genügend Traumlaub für zwei Tassen Tee mitgebracht... Hmm, warum nicht?\n\nAuf bessere Zeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[29582] = { id = 29582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greks verrückte Nacht", description = "Grek hatte gestern ziemlich üble Nacht.\n\nGlänzender Mumienmann kam in Greks Haus und sagte, Grek solle zu Managruft in Auchindoun gehen. Aber Grek versuchte noch Steckbrief zu lesen!\n\n<Greks Augen beginnen zu leuchten.>\n\nGrek weiß! Ihr gehen zu glänzendem Mumienmann und sagt ihm, Grek schickt Euch. Perfekter Plan!", sourceObjective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", completion = "Der Hohlschädel hat stattdessen Euch geschickt?\n\n<Konstrukteur Morphalius mustert Euch.>\n\nDann werdet Ihr wohl genügen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29583] = { id = 29583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eckert der Verrückte", description = "Ich bin ein erfahrener Ingenieur, ein brillanter Erfinder, der Mittelpunkt jeder Party und der beste Tänzer, den es jemals in Azeroth gegeben hat.\n\nAber nennt mich jemand so? Nein.\n\nDa hat man nur eine Begegnung mit einem Astralen und auf einmal nennt einen die ganze Welt \"den Verrückten\".\n\nGenau hier habe ich gestern einen gesehen, das schwöre ich! Er sagte, ich müsste ihm nur zur Managruft in Auchindoun folgen, dann würde ich einen gewaltigen Schatz bekommen und uraltes Wissen erlangen!", sourceObjective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", completion = "Ich hatte wirklich gehofft, dass der Gnom, den ich aufgesucht habe, meinem Ruf folgen würde.\n\n<Konstrukteur Morphalius mustert Euch.>\n\nNa ja, Ihr müsst mir genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29584] = { id = 29584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogufeuerteufel vernichten", description = "Als ob der Angriff noch nicht schlimm genug war, stecken die Mogu auch noch diese uralten Obstgärten in Brand.\n\nMir ist nicht klar, was sie damit bezwecken, aber wir müssen sie aufhalten. Durchkämmt und säubert diese Obstgärten, damit diese Leute weiterhin davon leben können.", sourceObjective = "Vernichtet 8 Mogufeuerteufel im Obstgarten Nektarhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29585] = { id = 29585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerspeier", description = "Wir kümmern uns seit Generationen um diese Obstgärten und stellen aus dem Nektar Most her. In all der Zeit haben wir gelernt, wie wir ein Feuer im Handumdrehen löschen können.\n\n<Hanae drückt Euch einen Krug Apfelmost in die Hand.>\n\nDer Apfelmost wird klebrig und dickflüssig, wenn man ihn mit zerstoßenem Ingwerblatt und Spucke vermischt. Damit lassen sich Feuer gut löschen.\n\nBitte, könnt Ihr versuchen, die Flammen unter Kontrolle zu bringen, wenn Ihr da draußen seid? Ich habe schon Ingwerblatt daruntergemischt, Ihr müsst nur noch hineinspucken.", sourceObjective = "Nutzt den Nektarhauchmost, um 12 Feuer im Obstgarten Nektarhauch zu löschen.", completion = "Eben war jemand hier und sagte, dass die Flammen langsam erlöschen.\n\nWir sind Euch zu großem Dank verpflichtet. Ich kann Euch unmöglich angemessen belohnen, aber nehmt das doch bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29586] = { id = 29586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gesplitterte Pfad", description = "Zuerst... vor den Kriegsschreien... hörten wir die Bäume.\n\nSie stöhnten, knarrten und stürzten schließlich zu Boden, als die Mogu sich den Weg durch den Wald bahnten. Sie machten sich den Rückweg leichter...\n\nSie zerren unsere Freunde auf diesem Weg zurück zu den Ruinen westlich des Dorfes! Diese Ruinen waren seit Jahren verlassen – unsere Kinder spielen dort.\n\nWarum sollten die Mogu jetzt dorthin zurückkehren?", sourceObjective = "Folgt dem Weg der gefallenen Bäume von der Nordwestecke des Obstgartens Nektarhauch aus und findet das Lager der Moguräuber.", completion = "Das sieht nicht nach einer schnellen Entführung aus. Die haben etwas Größeres im Sinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29587] = { id = 29587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebunden", sourceObjective = "Befreit 10 gefesselte Bauern von Nektarhauch im Lager Gormal.", completion = "Die Pandaren waren in alten Zeiten der Moguregentschaft unterworfen - das werden wir nie wieder zulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29590] = { id = 29590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Totenwächter", description = "Ein schreckliches, überirdisches Wesen sucht die Welt der Geister und die der Lebenden heim. Wir nennen es Shirrak.\n\nEs kann nur in Eurem Reich verletzt werden. Bitte helft uns, diesen Alptraum zu beenden.", sourceObjective = "Tötet Shirrak den Totenwächter und kehrt zu dem Draeneigeist zurück.", completion = "Vielleicht werden wir jetzt endlich Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29591] = { id = 29591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister", description = "Die Auchenai haben all unseren Werten den Rücken gekehrt. Sie erwecken die Toten und halten sie als ihre unheiligen Diener!\n\nDas muss ein Ende haben. Bringt diesen Geistern den Frieden und tötet alle, die sie zu Untoten gemacht haben.", sourceObjective = "Tötet 5 erboste Skelette, 5 tobende Skelette und 3 Totenbeschwörer der Auchenai. Kehrt dann zur gequälten Seelenpriesterin in der Auchenaikrypta zurück.", progress = "Sprecht mich erst wieder an, wenn die Tat vollbracht ist.", completion = "Die Toten gehören ins Reich der Geister, so wie Ihr in dieses Reich gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[29592] = { id = 29592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caster Legendary BREADCRUMB TRACKER" }
quests[29593] = { id = 29593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft sie, wo es schmerzt", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, {class}?", sourceObjective = "Stehlt 3 Stapel Höllenfeuervorräte und kehrt zu Steingardist Stok'ton im Höllenfeuerbollwerk zurück.", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29594] = { id = 29594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft sie, wo es schmerzt", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, {class}?", sourceObjective = "Stehlt 3 Stapel Höllenfeuervorräte und kehrt zu Vorhutsspäher Chadwick im Höllenfeuerbollwerk zurück.", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29595] = { id = 29595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wird gut", description = "Da habt Ihr ja ein ziemliches Abenteuer hinter Euch, {name}. Dabei habt Ihr die Auchenaikrypta noch nicht einmal betreten.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden, noch war ich Teil von Exarch Maladaars verwerflichen Experimenten in der Nekromantie. Levixus habt Ihr bereits vernichtet, aber Maladaar quält weiter die Geister in der Krypta.\n\nIch habe eine simple Bitte an Euch. Betretet die Auchenaikrypta und sprecht mit dem Draeneigeist dort. Ihr müsst Exarch Maladaar vernichten.", sourceObjective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr Euch in die Auchenaikrypta begebt und mit dem Draeneigeist sprecht.", completion = "Willkommen in der Auchenaikrypta, {name}. Unsere beiden Welten treffen sich hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29596] = { id = 29596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Exarchen", description = "Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar und muss aufgehalten werden.\n\nTötet ihn zum Wohle aller, dem der Toten und dem der Lebenden.", sourceObjective = "Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.", completion = "Ihr habt unserem Reich einen großen Dienst erwiesen. Wir werden Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29597] = { id = 29597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Exarchen", description = "Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar, wenn er nicht aufgehalten wird.\n\nTötet ihn zum Wohle aller, dem der Toten und der Lebenden.", sourceObjective = "Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[29598] = { id = 29598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarethas Ablenkungsmanöver", description = "Taretha war es, die ursprünglich für das Ablenkungsmanöver in Durnholde sorgte und Thrall die Flucht ermöglichte.\n\nNun haben die Ewigen Taretha gefangen genommen. Wenn wir nicht eingreifen, wird es kein Ablenkungsmanöver geben. Nehmt die Brandsätze, die ich Euch gegeben habe, und brennt die Internierungsbaracken nieder.", sourceObjective = "Reist nach Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.\n\nSprecht mit Thrall im Kellergefängnis von Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.", progress = "Wer seid Ihr?", completion = "Ihr seid mit Taretha befreundet? Das also ist ihr neuer Plan? Also gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[29599] = { id = 29599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Durnholde", description = "Ich habe große Pläne für mein Volk, <Fremder/Fremde>.\n\nEines Tages wird es seine Unterdrücker stürzen und sich erheben. Es wird die Ketten sprengen, die es halten und dies wird die Geburtsstunde der orcischen Horde sein.\n\nWir fliehen, wenn Ihr bereit seid.", sourceObjective = "Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.\n\nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.", completion = "Ihr habt eine großartige Aufgabe vollbracht, {name}. Nun müssen die Erinnerungen des jungen Kriegshäuptlings an diese Ereignisse wieder so verändert werden, wie sie einst waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[29600] = { id = 29600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Urteil", description = "Diese Teiche sind etwas ganz Besonderes: In Pandaria gibt es sonst keinen Ort, der Leben so viel Nahrung bietet.\n\nLeider hat das auch die Aufmerksamkeit der einheimischen Fauna auf sich gezogen. Vor kurzem haben Drachenschildkröten herausgefunden, dass es auf der Ebene direkt über uns viele Teiche voller Krötenlaich gibt. Jetzt haben sie sich dort oben breitgemacht, trampeln die Lotusblüten nieder und greifen meine Arbeiter an.\n\nEinzeltiere sind nicht sonderlich gefährlich, aber in Gruppen können sie ganz schön gemein sein. Bitte, wenn Ihr ein wenig Kraft erübrigen könnt, helft uns, sie loszuwerden.", sourceObjective = "Tötet 16 Klingenrückenschnapper bei den Teichen der Reinheit.", progress = "<Yue seufzt.>\n\nWären wir mit der Pflege nicht so nachlässig gewesen, wäre es nicht so weit gekommen.", completion = "Ich bin Euch dankbar, {name}.\n\nBitte nehmt dies als Zeichen meiner Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29601] = { id = 29601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturführer des Dunkelmond-Jahrmarkts", description = "Habt Ihr eine Ausgabe des Naturführers des Dunkelmond-Jahrmarkts, <mein Freund/meine Liebe>? Das ist ein wirklich nützliches Buch.\n\nMit seiner Hilfe könnt Ihr auf Euren Reisen durch Azeroth wertvolle Artefakte identifizieren. Die Beschreibungen sind so genau, dass Ihr leicht erkennen könnt, ob Ihr Euren fünfhundertsten Messingknopf gefunden habt oder einen seltenen Schatz, nach dem sich die Sammler des Dunkelmond-Jahrmarkts die Finger lecken würden." }
quests[29602] = { id = 29602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Greif gefunden" }
quests[29603] = { id = 29603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Versorgerin gefunden" }
quests[29604] = { id = 29604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Ankunftsfilm am östlichen Tempel gesehen" }
quests[29605] = { id = 29605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Die Sethekk verließen Skettis, als Auchindoun explodierte.\n\nMein Bruder Syth gehörte zu ihren Anführern. Auf seinen Befehl suchten wir die Ruinen auf und stellten uns unserem Gott.\n\nNach kurzer Zeit warf mich Syth jedoch aus den Hallen, weil mir Zweifel an ihren Fähigkeiten kamen. Er erlaubte mir nicht, meine Schwester Lakka mitzunehmen. Werdet Ihr mir helfen, sie zu retten?", sourceObjective = "Befreit Lakka aus ihrer Gefangenschaft. Kehrt zu Isfar in den Sethekkhallen zurück, wenn Ihr die Rettung abgeschlossen habt.", completion = "Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Ich werde die Todesriten für ihn vollziehen, wenn ich in Skettis ankomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29606] = { id = 29606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Erbe", description = "Terokk, der Held von Arakkoa, verschwand eines Tages plötzlich und ließ nur seine Maske und seinen Speer zurück.\n\nDunkelwirker Syth hat sie immer noch in seinem Besitz und Klauenkönig Ikiss wacht über seinen Speer.\n\nEs würde meinem Volk viel bedeuten, wenn wir die Gegenstände zurückbekommen würden.", sourceObjective = "Bringt Terokks Maske und Terokks Federkiel zu Isfar in den Sethekkhallen.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinem Volk zurückgebe", sourceObjectiveStatus = "unverified-source-field" }
quests[29607] = { id = 29607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen der Begierde", description = "Ich habe einen Kunden, der sich für die Augen der kobaltblauen Schlangen interessiert, die sich hier angesiedelt haben.\n\nWenn Ihr mir einige dieser seltenen Edelsteine besorgen könntet, würde ich den Profit mit Euch teilen.\n\nEinverstanden?", sourceObjective = "Händler Vijaad in den Sethekkhallen möchte, dass Ihr ihm 3 Kobaltaugen bringt.", progress = "Habt Ihr die Augen bekommen?", completion = "Wunderbare Stücke, gut gemacht!\n\nHier ist Euer Anteil, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29608] = { id = 29608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in Dalaran", description = "Willkommen in Nordend, {name}. Man hat mich gebeten, die Reise nach Dalaran für Euch zu arrangieren, damit Ihr dort unsere Verbündeten treffen könnt.\n\nReitet auf einem Greifen nach Dalaran und sucht nach der Landung unser Gasthaus Zum Gefeierten Helden auf. Sprecht dort mit Isirami Sanftwind.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Mit dem Portal in der Silbernen Enklave könnt Ihr dann rasch nach Sturmwind zurückreisen.", sourceObjective = "Macht einen Greifenritt nach Dalaran und sprecht mit Isirami Sanftwind im Gasthaus Zum Gefeierten Helden.", completion = "Willkommen in Dalaran! Dieses Gasthaus gehört zur Silbernen Enklave, dem offiziellen Hauptquartier der Allianz in dieser Stadt.\n\nVergesst nicht, Euren Ruhestein hier zu binden, damit Ihr rasch in die Stadt reisen und nebenan das Portal nach Sturmwind nutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29609] = { id = 29609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in Dalaran", description = "Willkommen in Nordend. Man hat mich gebeten, Eure Reise nach Dalaran zu arrangieren, damit Ihr unsere Freunde in der Stadt kennenlernen könnt.\n\nSprecht mit mir und nehmt einen Flug nach Dalaran an. Begebt Euch nach der Landung zum Gasthaus \"Das Rattenloch\".\n\nRedet dort mit Uda dem Biest.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Dann könnt Ihr durch das Portal in Sonnenhäschers Zuflucht rasch nach Orgrimmar reisen.", sourceObjective = "Lasst Euch vom Flugmeister einen Flug nach Dalaran geben und sprecht mit Uda dem Biest im Rattenloch.", completion = "Ich habe Euch erwartet. Dieses Gasthaus gehört zu Sonnenhäschers Zuflucht, der Hordenenklave von Dalaran.\n\nDenkt daran, Euren Ruhestein hier zu binden, damit Ihr rasch zur Stadt kommen und das Portal nach Orgrimmar, draußen neben dem Brunnen, benutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29610] = { id = 29610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Erstes Eintreffen des Spielers" }
quests[29611] = { id = 29611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Krieges", description = "Lok'tar ogar, {race}. Ich bin Nazgrim.\n\nHiermit befehle ich Euch, Euch unverzüglich in der Feste Grommash zu melden.\n\nAlle im Dienst der Horde haben ihrem neuen Kriegshäuptling die Treue zu schwören.\n\nLasst ihn lieber nicht warten, {race}.", sourceObjective = "Sprecht mit General Nazgrim in der Feste Grommash.", completion = "Ah, gut. Ihr seid da. Und keinen Augenblick zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[29612] = { id = 29612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Krieges", description = "Lok'tar ogar, <alter Freund/alte Freundin>. Es ist schon zu lange her, seit wir miteinander gesprochen haben.\n\nEs freut mich zu sehen, dass Ihr heil aus den Tiefen von Vashj'ir hervorgekommen seid.\n\nIch bin jetzt hier in der Feste Grommash stationiert.\n\nAlle im Dienst der Horde haben ihrem neuen Kriegshäuptling die Treue zu schwören.\n\nLasst ihn lieber nicht warten, {name}.", sourceObjective = "Sprecht mit General Nazgrim in der Feste Grommash in Orgrimmar.", completion = "Ah, gut. Ihr seid da. Und keinen Augenblick zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[29613] = { id = 29613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gerechtes Schicksal", description = "Kriegsherr Kalithresh leitet Operation Dampfkammer.\n\nEr muss sterben, {name}. Die Naga lassen uns keine andere Wahl als Gewalt.\n\nZeigt ihm keine Gnade.", sourceObjective = "Tötet Kriegsherr Kalithresh und kehrt zu Behüterin Jhang in der Dampfkammer zurück.", completion = "Ich wünschte, das wäre nicht nötig gewesen, aber die Naga haben alle Verhandlungsangebote abgelehnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29614] = { id = 29614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung ist der Schlüssel", description = "Die Naga haben sich mit den Lepragnomen verbündet, um eine schreckliche Krankheit in den Zangarmarschen zu verbreiten. Man begegnet ihr schon überall in der Dampfkammer.\n\nVernichtet alles, das bereits befallen ist, und bringt mir das mittlere Zahnrad von Robogenieur Dampfhammer. Beeilt Euch!", sourceObjective = "Tötet 3 Sumpfoberanführer und 6 Aussätzige des Echsenkessels und erbeutet ein verstrahltes Zahnrad von Robogenieur Dampfhammer. Kehrt dann zu Naturalist Biss in der Dampfkammer zurück.", progress = "Geht so sorgfältig wie möglich vor. Das Schicksal der Zangarmarschen hängt davon ab.", completion = "Ich bin froh, dass wir die Krankheit eingedämmt haben, bevor sie sich in den Zangarmarschen ausbreiten konnte. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29615] = { id = 29615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrufer Klaue und die Wasserdiebin", description = "Die Naga versuchen schon seit längerem, das Wasser aus den Zangarmarschen abzupumpen. Die Dampfkammer ist der Dreh- und Angelpunkt dieser Operation. Überwacht wird sie von Hydromantin Thespia.\n\nIhr Tod würde die Naga empfindlich treffen.", sourceObjective = "Tötet Hydromantin Thespia und kehrt zu Windrufer Klaue in der Dampfkammer zurück.", progress = "Habt Ihr die Wasserdiebin beseitigt?", completion = "Vielleicht können wir dem Land das verzweifelt benötigte Wasser nun zurückgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29616] = { id = 29616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Dampfkammer", description = "Bisher ist es uns nicht gelungen, die Naga in der Dampfkammer, wo sich ihre Pumpenzentrale befindet, aufzuhalten.\n\nZum Glück versucht die Expedition, die ich ausgesandt habe, das zu ändern. Würdet Ihr Euch in die Dampfkammer begeben und Behüterin Jhang Eure Hilfe anbieten?", sourceObjective = "Sprecht mit Behüterin Jhang in der Dampfkammer.", completion = "Ich danke den Sternen für Euch! Wir benötigen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29617] = { id = 29617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tiankloster", description = "Aus ganz Pandaria sind Leute angereist, um sich im Tiankloster gleich nördlich von hier ausbilden zu lassen. Wahrscheinlich, weil sie niemanden abweisen. Sie kümmern sich um Jinyu, Ho-zen... oder selbst Auswärtige wie Euch!\n\nMeine Freundin, Lin, ist gerade erst vor ein paar Wochen im Kloster aufgenommen worden. Wenn Ihr mehr über die Ausbildung bei unseren Mönchen erfahren möchtet, solltet Ihr vielleicht mit ihr sprechen!", sourceObjective = "Sprecht mit Lin Zartpfote im Tiankloster im Jadewald.", completion = "Ihr seid in aufregenden Zeiten hier eingetroffen. Der Hohe Älteste Wolkensturz hat zugestimmt, eine neue Klasse Schüler im Kloster aufzunehmen. Dies könnte meine Chance sein, endlich zu lernen, wie man kämpft!", sourceObjectiveStatus = "unverified-source-field" }
quests[29618] = { id = 29618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hohe Älteste", description = "Wie außergewöhnlich, jemanden so fremdländisches wie Euch hier in unserem Tempel begrüßen zu dürfen, {class}. Seid Ihr an einer Ausbildung interessiert?\n\nIhr... Ihr seht sehr stark aus. Es sollte Euch keine Mühe machen, im Kloster aufgenommen zu werden. Vielleicht solltet Ihr mit dem Hohen Ältesten dort oben auf dem Balkon sprechen.", sourceObjective = "Sprecht mit dem Hohen Ältesten Wolkensturz im Tiankloster im Jadewald.", completion = "Willkommen im Tiankloster. Ich hörte, dass die junge Lin Euch schon von unserer Rolle hier in unserem Dorf in den Bergen unterrichtet hat.\n\nWir verfügen nicht über viel Erfahrung mit Fremden. Es wäre uns eine große Ehre, wenn Ihr Euch an der Seite unseres Nachwuchses ausbilden lassen wollt. Wir können Euch aber kaum etwas anbieten, {class}... außer vielleicht Wissen und das Verständnis dafür, was es heißt, ein Pandaren zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29619] = { id = 29619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höflicher Gast", description = "Ich habe es schon gehört! Der Hohe Älteste möchte, dass Ihr eine Ausbildung zusammen mit uns macht!\n\nFür uns Schüler wird es ein Bankett geben... Und Ihr solltet vielleicht ein Geschenk mitbringen, als Zeichen der Höflichkeit.\n\nDie Orangen im Hain südlich des Tempels sind gerade reif und sehr süß. Bringt einige davon mit zum Bankett.", sourceObjective = "Sammelt 8 reife Orangen im Orangenhain südlich des Tianklosters ein.", progress = "Seid Ihr bereit für das Bankett? Ich bin ja so aufgeregt.", completion = "Die sind perfekt. Was für ein tolles Geschenk, {name}!\n\nOh, ich? Ich bringe natürlich Bier mit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29620] = { id = 29620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Bankett", description = "Das Bankett sollte jetzt jeden Moment beginnen. Sucht den Hohen Ältesten auf und erweist ihm die Ehre. Ich werde direkt hinter Euch sein.", sourceObjective = "Sprecht mit dem Hohen Ältesten Wolkensturz im Bankettareal im Tiankloster.", progress = "Die Ausbildung wird noch früh genug beginnen, junger {class}. Aber zunächst müssen wir reden, trinken und essen.\n\nAllerdings imponiert mir Eure Disziplin.", completion = "Damit sind die Einführungen beendet. Ihr werdet jetzt bald mit Eurer Ausbildung beginnen können.\n\nAllerdings... könnt Ihr erst beginnen... NACHDEM wir noch einen Krug Bier getrunken haben. Oder vielleicht zwei, was meint Ihr, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29622] = { id = 29622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginn der Ausbildung", description = "<Xiao sieht nicht von seiner Schüssel auf.>\n\nHey, <neuer Schüler/neue Schülerin>! Schön, dass Ihr das Bankett überlebt habt! Übung 1: Bestanden!\n\n<Xiao isst geräuschvoll.>\n\nIhr solltet mit Ausbilder Xann sprechen. Er erwartet Euch sicher schon zu den täglichen Übungen.\n\n<Er isst weiter. Ihr vermutet, dass er Euch nichts weiter zu sagen hat.>", sourceObjective = "Meldet Euch bei Ausbilder Xann im Tiankloster im Jadewald.", completion = "Erst trinkt Ihr zu viel Bier und dann kommt Ihr zu spät zu den Übungen? Ihr scheint Euch ja schon an die Pandaren-Kultur gewöhnt zu haben.\n\nAlso fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29623] = { id = 29623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfektion", description = "Perfektion kann durch Wiederholung erlangt werden. Alle Schüler in der Ausbildungsarena da unten werden früher oder später die perfekten Formen finden... wenn sie nicht vorher aufgeben. Das ist eine Tatsache.\n\nIch möchte Euch empfehlen, sich ihnen anzuschließen, {name}. Als ein Ehrengast des Klosters seid Ihr schließlich nicht angehalten, die 10.000 Wiederholungen täglich auszuführen. Folgt einfach für ein paar Minuten den Beispielen derjenigen, die es vormachen.", sourceObjective = "Führt 12 Übungsschläge in der Ausbildungsarena des Klosters aus, indem Ihr die Beispiele nachahmt.", progress = "Auch ich habe einst in diesem Bereich meine Ausbildung gemacht. Damals war alles noch viel einfacher.", completion = "Ihr kämpft aber nicht zum ersten Mal, oder? Eure Formen sind nicht perfekt, aber durchaus geübt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29624] = { id = 29624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte recht aufmerksam", description = "In Eurer nächsten Prüfung geht es um Konzentration und Aufmerksamkeit. Ich möchte, dass Ihr Eure Fähigkeiten an den Sandsäcken unten im Übungsbereich verfeinert.\n\nDie Säcke sind jeweils in Zweiergruppen aufgehängt. Wenn ich \"links\" rufe, greift Ihr den Sack auf der linken Seite an. Wenn ich \"rechts\" rufe, greift Ihr den Sack auf der rechten Seite an.\n\nWenn Ihr diesen einfachen Anweisungen nicht folgen könnt, wird die Aufgabe umso schwerer.\n\nUnd jetzt schlagt auf diese Säcke ein, bis sie platzen, {name}.", sourceObjective = "Zerstört 2 Sandsäcke. Folgt den Anweisungen von Ausbilder Xann, um zu entscheiden, welche Säcke angegriffen werden sollen.", progress = "Worauf wartet Ihr?", completion = "Ihr zählt vielleicht nicht zur regulären Schülerschaft hier, aber trotzdem könnt Ihr ja etwas lernen.\n\nIch versichere Euch, dass die Fähigkeit, schnell von einem Ziel zum anderen wechseln zu können, in zukünftigen Kämpfen von großem Wert sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29626] = { id = 29626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klosterwart Wu", description = "Wir haben nicht viele Regeln hier, aber eine davon solltet Ihr Euch merken. Wer essen will...\n\n<Xiaos Magen knurrt vernehmlich.>\n\n...muss etwas dafür tun. Der Klosterwart Wu kann Euch Eure heutigen Arbeiten zuweisen. Er befindet sich auf dem Markt im Westen.", sourceObjective = "Meldet Euch bei Klosterwart Wu im Tiankloster im Jadewald.", completion = "<Wu spricht Euch kurz angebunden an.>\n\nIhr seid {name}, oder? Der Lieblingssohn des Hohen Ältesten? Ja, Ihr wart doch auch auf dem Bankett.\n\nAber ich werde Euch nicht bevorzugt behandeln, junger Herr. Ihr werdet hier genauso hart arbeiten wie alle anderen Pandaren-Schüler.\n\nVielleicht sogar noch härter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29627] = { id = 29627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ordentliche Waffe", description = "Aber immer der Reihe nach.\n\nOrdentliche Schüler benötigen eine ordentliche Waffe. Und die vorbildlichen Schüler bauen sich ihre eigenen Waffen... oder sammeln zumindest die Materialien dafür selbst ein.\n\nDie in der Nähe wachsenden Ruten sollten eine gute Waffe ergeben. Und außerdem müsst Ihr noch Schwarznussextrakt kaufen, um das Holz zu behandeln. Und wo Ihr schon mal Einkaufen geht, könnt Ihr gleich etwas Bier mitnehmen, damit...\n\n<Wu hält inne.>\n\nAlso, Ihr wisst schon, was man mit Bier so macht.", sourceObjective = "Besorgt 6 Rattanruten aus der Gegend um den Markt vom Tiankloster.\n\nKauft eine Phiole Schwarznussextrakt von Juni Weißblüte.\n\nKauft 3 dreifach bittere Bräue von Braumeister Lei Kanglei.", progress = "<Wu schaut Euch erwartungsvoll an.>", completion = "<Klosterwart Wu nimmt dankbar die Materialien entgegen.>\n\nBis zum Ende Eurer Ausbildung werde ich Euch eine Waffe gefertigt haben. Und jetzt weiter mit der echten Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29628] = { id = 29628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein starker Rücken", description = "Einige unserer Schüler haben einen... enormen Appetit. Und manchmal haben wir Schwierigkeiten, genug Nahrung für alle bereitzustellen. In diesen Fällen müssen wir um Hilfe bitten.\n\nIn einem kleinen Haus im Nordwesten lebt eine freundliche, ältere Dame, die sich bereit erklärt hat, etwas Eintopf für unsere Schüler zu kochen. Ihr müsstet nur zu ihr gehen und ihn abholen.", sourceObjective = "Holt einen kochenden Kessel von Mutter Wu im Wachsgehölz ab und kehrt dann zu Klosterwart Wu im Tiankloster zurück.", completion = "Ich werde mich darum kümmern, dass der Eintopf gerecht unter den Schülern aufgeteilt wird.\n\nNachdem ich etwas für mich abgezweigt habe, versteht sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29629] = { id = 29629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ruhige Hand", description = "Der Schwarznussextrakt, den Ihr von Juni Weißblüte gekauft habt, ist nur einer von vielen Extrakten, den wir hier für verschiedene Verwendungen bereit halten.\n\nRötelblattextrakt zum Beispiel kann man aus den Blumen in der Gegend vom Wachsgehölz im Westen gewinnen. Aus einer einzigen Blume erhält man mehrere Einheiten, aber man benötigt eine ruhige Hand, um der Blume den gesamten Extrakt zu entziehen.", sourceObjective = "Besorgt 80 Phiolen Rötelblattextrakt von den Rötelblattbüscheln im Wachsgehölz.", progress = "Die früheren Kräutermeister sollen in der Lage gewesen sein, 20 Phiolen Extrakt aus einer einzelnen Blume zu gewinnen.", completion = "Und nicht vergessen, die Hände zu waschen. Der Rötelblattsaft geht nie wieder ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[29630] = { id = 29630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und eine harte Faust", description = "Die Grünwaldgeister im Wachsgehölz westlich von hier stellen zwar keine unmittelbare Gefahr für uns dar, aber ihre Anzahl hat sich in letzter Zeit alarmierend erhöht - und damit auch ihre verschlagenen Possen.\n\nEs gehört zu unserer Pflicht als Hüter des Waldes, das Gleichgewicht zu wahren. Und Eure Pflicht ist es, diese Geister wieder zurück in die Erde zu befördern.", sourceObjective = "Erledigt 10 Grünholztrickster im Wachsgehölz.", completion = "Ich danke Euch, {name}. Die Geister werden sich in wenigen Tagen schon wieder vermehrt haben, aber zumindest im Augenblick ist das Gleichgewicht gewahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29631] = { id = 29631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Feuereifer", description = "Kann ich Euch um einen Gefallen bitten, {name}?\n\nBevor ich in das Kloster kam, hatte ich keinerlei Erfahrung mit Kämpfen. Im Zuge meiner Ausbildung wurde ich zwar auch im Umgang mit Waffen geschult, aber niemals wirklich gefährlichen Situationen ausgesetzt. Aber jetzt bin ich nicht mehr in der Ausbildung, sondern ein voll bezahlter Wächter. Man erwartet von mir, dass ich das Gebiet um jeden Preis verteidige.\n\nMit den Grünwaldgeistern kann ich es aufnehmen, aber die Tiger im westlichen Wachsgehölz sind eine Nummer zu groß für mich. Könntet Ihr Euch vielleicht um sie kümmern?", sourceObjective = "Tötet 6 Wachsgehölztiger.", progress = "Bitte sagt niemanden etwas von unserer Vereinbarung. Meine Feigheit ist mir peinlich.", completion = "Ich danke Euch, {name}. Tausend Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29632] = { id = 29632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zum Kampf", description = "Also, jetzt wollen wir doch mal sehen, aus welchem Holz Ihr geschnitzt seid.\n\nIhr trefft überall im Kloster auf Schüler. Fordert sie zu einem Kampf heraus. Bringt sie an ihre Grenzen. Ihnen wurde schließlich das gleiche aufgetragen wie Euch.\n\nEgal, ob Sieg oder Niederlage – aus dem Kampf gehen beide Kontrahenten gestärkt hervor.", sourceObjective = "Besiegt 8 Schüler von Tian in Übungskämpfen im Tiankloster.", progress = "In Eurer Heimat mögt Ihr zu den Helden zählen. Hier aber müsst Ihr Euch erst noch beweisen.", completion = "<Meister Steinfaust schaut Euch misstrauisch an.>\n\nAlso gut, ich habe genug gesehen. Schluss mit dem Verprügeln der jungen Schüler. Wir machen mit der nächsten Ausbildungsphase weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29633] = { id = 29633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wehrhafte Zhi-Zhi", description = "Auf den Hügeln rechts von mir findet Ihr einen Ho-zen namens Zhi-Zhi. Auch er hat genug Übungskämpfe gewonnen, um einen Rang aufzusteigen. Ich denke, er sollte eine größere Herausforderung für Euch darstellen.\n\nFordert ihn heraus und versucht, ihn zu besiegen.", sourceObjective = "Besiegt Zhi-Zhi im Tiankloster.", completion = "Offensichtlich muss ich Euch schon wieder einen Rang aufsteigen lassen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29634] = { id = 29634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der uralte Husshun", description = "Die Jinyu sind schon seit langer Zeit Verbündete der Pandaren und die Mitglieder ihres Volkes sind jederzeit in unserem Kloster willkommen. Husshun, einer ihrer erfahreneren Schamanen, ist einer unserer neuen Schüler.\n\nSeine Fähigkeiten als Mönch sind höchstens Mittelmaß, aber er ist dennoch ein starker Gegner. Er sollte die Herausforderung darstellen, nach der Ihr sucht.", sourceObjective = "Fordert Husshun im Tiankloster heraus und besiegt ihn.", completion = "Ich muss Euch warnen, {class}:\n\nWenn Ihr weiterhin meine besten Schüler besiegt, kann ich Euch nicht weiter unterrichten. Und dann habt Ihr keinen Grund mehr, meine Gesellschaft zu genießen.\n\nDenkt daran, bevor Ihr weiter mit solcher Geschwindigkeit meine anderen Schüler ausschaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29635] = { id = 29635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der hungrige Xiao", description = "Meinen besten Schüler, Xiao, habt Ihr bereits am Tisch beim Bankett kennengelernt. Ich selbst hätte ihm schon längst seinen Abschluss gegeben, aber Ausbilder Xann besteht darauf, dass er noch mehr an seiner Disziplin arbeiten müsse.\n\nMeiner Meinung nach ist Disziplin vollkommen unwichtig, solange man alle seine Kämpfe gewinnt. Ich würde gern sehen, ob Xiao seine Siegesserie gegen Euch fortsetzen kann.", sourceObjective = "Fordert Xiao im Tiankloster heraus und besiegt ihn.", progress = "Dem jungen Xiao winkt eine große Zukunft als Kampfkünstler. Ich wünsche Euch viel Glück für Euren nächsten Kampf.", completion = "Ich kann nicht behaupten, dass ich überrascht bin, {race}. Ihr seid ein herausragender Kämpfer und ein exzellenter {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29636] = { id = 29636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langer Weg", description = "Ich habe Euch alles gelehrt, was in meiner Macht steht, {name}. Jetzt ist es an der Zeit, dass Ihr Euch an die Ausbilderin Myang wendet.\n\nDie Kämpfe, die sie ausrichtet, sind weniger traditionell als meine. Aber der Weg von reisenden Abenteurern wie Euch ist unvorhersehbar und eine umfangreiche Kenntnis der verschiedenen Kampfstile könnte sich als großer Vorteil erweisen.\n\nLebt wohl, {name}, und viel Glück bei Eurer weiteren Ausbildung.", sourceObjective = "Meldet Euch bei Ausbilderin Myang im westlichen Bereich des Tianklosters.", completion = "Seid gegrüßt, {name}. Ihr habt Euch einen guten Ruf unter unseren Schülern hier erworben. Viele Eurer Übungspartner haben mir von Euch berichtet - zumeist mit aufgeplatzten und geschwollenen Lippen.\n\nIch freue mich schon darauf, Euch zu betreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29637] = { id = 29637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenschlägerei", description = "Meister Steinfaust hat Euch gelehrt, wie Ihr gegen einen einzelnen Gegner bestehen könnt. Jetzt erlernt Ihr den Kampf gegen eine Gruppe von Gegnern.\n\nZum Beispiel gegen fünfzig.\n\nBegebt Euch in den Ring des Inneren Fokus da unten und entzündet das Feuerwerk, wenn Ihr bereit seid. Meine Helfer werden gemeinsam auf Euch losstürzen.\n\nVersucht, den Ansturm zu überleben.", sourceObjective = "Entzündet das Kloster-Feuerwerk im Ring des Inneren Fokus und überlebt die zwei Minuten dauernde Massenschlägerei.", progress = "Viel Glück, {name}.", completion = "Euer Kampfstil ist bemerkenswert, {name}. Die anderen Schüler könnten viel von Euch lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29639] = { id = 29639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Bravour bestanden", description = "Ihr habt alle Prüfungen bestanden, die wir Euch gestellt haben, {name}. Es ist an der Zeit, dass Ihr Euch jetzt um größere und wichtigere Angelegenheiten kümmert.\n\nAber zuvor gibt es noch ein Bankett! Der Hohe Älteste erwartet Euch im Bankettareal, um die Beendigung Eurer Klosterausbildung gebührend zu feiern.", sourceObjective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Tiankloster im Jadewald.", completion = "Ich gratuliere Euch, {name}. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29640] = { id = 29640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Spion To'gun", description = "Der Schattenrat hat die meisten unserer Spione bereits getötet, aber To'gun, der fliehen konnte, war so dumm zurückzukehren!\n\nIhr müsst ihn finden. Er ist unvernünftig, aber wir müssen herausfinden, was er weiß.", sourceObjective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", completion = "Wäret Ihr so nett, mir aus dem Käfig zu helfen? Er ist ein wenig beengt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29641] = { id = 29641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeleninstrumente", description = "Sie haben mich gefoltert, damit ich ihnen alles verrate, was ich weiß.\n\nDie anderen haben sie an Höllenschlund verfüttert, ich hätte als Nächstes dran sein sollen. Aber ich habe ihnen nichts verraten!\n\nSie benutzen spezielle Geräte, damit ihre Beschwörungen mächtiger werden. Diese Geräte müsst Ihr stehlen!", sourceObjective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionin Grik'tha im Schattenlabyrinth von Auchindoun.", progress = "Habt Ihr To'gun gefunden?", completion = "Dies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[29642] = { id = 29642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Auchindoun", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", sourceObjective = "Meldet Euch bei Feldkommandeur Mahfuun im Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", completion = "Wurde auch Zeit, dass Ihr eintrefft.\n\nMehlisah hat bereits vor Tagen angekündigt, dass sie Hilfe schicken würde. Und wir kämpfen hier noch länger!", sourceObjectiveStatus = "unverified-source-field" }
quests[29643] = { id = 29643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Blutes", description = "Vor zwei Jahren beschwor der Schattenrat ein Wesen, das eine Schneise der Verwüstung in Auchindoun hinterließ.\n\nLest den Kodex des Blutes, um herauszufinden, was damals geschah. Seid jedoch vorsichtig, denn Großmeister Vorpil beschützt ihn mit seinem Leben.", sourceObjective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig nicht in Ordnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[29644] = { id = 29644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Labyrinths", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren!\n\nMan nennt es Murmur und es droht, den Schattenrat zu überrennen und zu entkommen!", sourceObjective = "Vernichtet Murmur und meldet Euch danach bei Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun.", completion = "Ich schüttele mich bei dem Gedanken, was hätte passieren können, wenn Murmur entkommen wäre.\n\nDanke, mutiger Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[29645] = { id = 29645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschafter Höllenschlund", description = "Als die Kabale unsere Spione entdeckte, verfütterte sie alle an Botschafter Höllenschlund.\n\nUnsere Männer verdienen Gerechtigkeit. Tötet die Ritualisten, die Höllenschlund binden und vernichtet dann auch ihn.\n\nEr hat dieses Schicksal schon lange verdient.", sourceObjective = "Tötet 12 Ritualisten der Kabale sowie Botschafter Höllenschlund und kehrt zu Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun zurück.", completion = "Das bringt zwar niemanden zurück, aber wenigstens wurde der Gerechtigkeit Genüge getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29646] = { id = 29646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Bravour bestanden", description = "So, ich habe Euch alles beigebracht, was ich konnte. Und die anderen offensichtlich auch.\n\nDer Hohe Älteste erwartet Euch im Bankettareal, um Euren Abschied gebührend zu feiern. Nicht, dass wir Euch gerne gehen lassen... Er feiert einfach gern.", sourceObjective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.", completion = "Ich gratuliere Euch, {name}. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29647] = { id = 29647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Bravour bestanden", description = "Die Krawallgrube war Eure letzte Herausforderung. Ihr habt alle Disziplinen gemeistert, die an dieser Schule gelehrt werden.\n\nEure Ausbildung begann mit einem Bankett und so soll sie auch enden. Der Hohe Älteste erwartet Euch im Bankettareal und ich werde gleich hinter Euch sein.", sourceObjective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.", completion = "Ich gratuliere Euch, {name}. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29649] = { id = 29649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Leben rettet", description = "Gunny stirbt an einem mächtigen Fluch, {name}.\n\nGroßhexenmeister Nethekurse benutzt zwei mystische Kohlefeuer zur Verstärkung seiner Kräfte. Vielleicht könnten wir mit etwas Glut aus einem Kohlefeuer diese dunkle Magie rückgängig machen.", sourceObjective = "Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", progress = "Habt Ihr die Glut dabei? Wir haben nicht viel Zeit.", completion = "Er war ein guter Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29650] = { id = 29650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsglut", description = "Caza'rez stirbt wie ein Feigling.\n\nGroßhexenmeister Nethekurse hat ihn mit einem schrecklichen Fluch belegt. Bringt mir etwas Glut aus seinen Kohlenpfannen. Vielleicht können wir die Magie damit umkehren, bevor es zu spät ist.", sourceObjective = "Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", progress = "Habt Ihr die Glut bekommen? Caza'rez verdient es, wie ein Krieger zu sterben.", completion = "Ich werde viele Lieder zu seinem Ruhm anstimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29651] = { id = 29651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Sterbenden", description = "Ihre Elitekrieger sind gnadenlos... so... mächtig.\n\n<Caza'rez spuckt Blut.>\n\nIhr müsst sie töten... sonst werden wir Kargath nie besiegen...", sourceObjective = "Caza'rez in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre der Zerschmetterten Hand, 2 Zenturionen der Zerschmetterten Hand und 2 Champions der Zerschmetterten Hand tötet.", completion = "Caza'rez ist... von uns gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29652] = { id = 29652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Gefallen", description = "Der alte Gunny macht's nicht mehr lange...\n\nErweist mir einen letzten Gefallen und tötet die größten, übelsten Höllenorcs, die Ihr finden könnt.\n\nIm Andenken an alte Zeiten, ja?", sourceObjective = "Gunny in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre, 2 Zenturionen und 2 Champions der Zerschmetterten Hand tötet.", completion = "Hätten wir ihn doch retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29653] = { id = 29653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Kriegshäuptlings", description = "Kargath war einst einer der größten Helden der Horde.\n\nDoch nun trägt er den falschen Mantel des Kriegshäuptlings. Bringt mir die nach ihm benannte Waffe, damit wir uns an seine früheren Heldentaten erinnern können und nicht an die Gräuel, die er heute anrichtet.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr einen Beweis für den Sieg über Kargath Messerfaust?", completion = "Wir dürfen den Orc nicht vergessen, der Kargath einst war, noch die Lektion, die uns sein Fall sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29654] = { id = 29654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wenden", description = "Es gibt nur einen Weg, um sicherzustellen, dass die Höllenorcs die Ehrenfeste und die Allianz nicht länger bedrohen.\n\nIhr Kriegshäuptling muss sterben.\n\nBringt mir die Waffe, die nach ihm benannt ist, damit wir seinen Tod niemals vergessen.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr einen Beweis für den Sieg über \"Kriegshäuptling\" Kargath Messerfaust mitgebracht?", completion = "Mit Eurer Hilfe haben wir dem Feind schweren Schaden zugefügt.\n\nDie Ehrenfeste war schon seit Jahren nicht mehr so sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29655] = { id = 29655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderes Tuch", description = "Kriegshetzer O'mrogg hat mehr mutige Soldaten auf dem Gewissen als jeder andere Feind, dem ich bisher begegnet bin. Er ist skrupellos, listig und äußerst mächtig.\n\nTötet ihn und bringt mir sein Kriegstuch. Wir werden ein Banner daraus nähen, sodass der Zorn der Horde für alle sichtbar ist.", sourceObjective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr das Tuch dabei?", completion = "Sehr gut. Nun werden diese blutgierigen Ungeheuer sehen, mit wem sie sich angelegt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29656] = { id = 29656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'mroggs Kriegstuch", description = "Sturmwind möchte Beweise für unsere Kriegserfolge sehen.\n\nWir könnten ihm Leichensäcke schicken, aber ich denke, das Kriegstuch von O'mrogg, Kargaths mächtigstem Krieger würde ihn mehr beeindrucken. Traut Ihr ihn Euch zu?", sourceObjective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr das Tuch dabei?", completion = "Meine Vorgesetzten werden damit sehr zufrieden sein. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29657] = { id = 29657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus großer Kraft folgt große Verantwortung", description = "<Ihr hört eine Stimme, leicht wie der Klang winziger Glocken, in Eurem Kopf.>\n\nIn der Mechanar entstehen durch die Technologie meines Volks Manazellen, Objekte, die eine gewaltige Energie in sich tragen.\n\nTötet Mechanolord Kapazitus, damit Kael'thas' Streitkräfte sich diese Macht nicht zu Nutze machen können.", sourceObjective = "A'dal bittet Euch, Mechanolord Kapazitus in der Mechanar der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29658] = { id = 29658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kalkulator", description = "<Eine leichte Brise streicht über Euer Gesicht.>\n\nNur noch eines bleibt zu tun.\n\nPathaleon der Kalkulator überwacht die meisten Operationen seines Herrn. Er persönlich trägt die Verantwortung für einen Großteil des Leids, das in letzter Zeit über die Welt gekommen ist.\n\nIch möchte, dass Ihr ihn vernichtet.", sourceObjective = "A'dal hat Euch gebeten, Pathaleon den Kalkulator in der Mechanar der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29659] = { id = 29659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schatz", description = "Ich spüre, dass eines der Artefakte meines Volkes gestohlen wurde und im Behälter der Legion aufbewahrt wird.\n\nSie dürfen nicht entdecken, wie mächtig es ist. Würdet Ihr die Torwächter töten und es wiederbeschaffen? Ich wäre Euch sehr dankbar.", sourceObjective = "Beschafft für A'dal den Blendenden Zorn aus dem Behälter der Legion in der Mechanar der Festung der Stürme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29660] = { id = 29660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Botanika", description = "Kael'thas und seinen Streitkräften ist es nicht gelungen, die vielen Kreaturen in der Botanika niederzuwerfen. Wir müssen versuchen, ihre Fehler wiedergutzumachen.\n\nDer erste Schritt ist die Eliminierung ihrer Streitkräfte, damit sie keinen weiteren Ärger mehr verursachen können.", sourceObjective = "A'dal möchte, dass Ihr Kommandantin Sarannis, Hochbotaniker Freywinn und Dorngrin den Hüter in der Botanika der Festung der Stürme tötet.", completion = "Die Kreaturen an diesem Ort hätten sie früher oder später auch ohne unser Eingreifen getötet. Wir haben zum Besten aller gehandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29661] = { id = 29661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion trockenen Fells", description = "Über die Meditation werde ich versuchen herauszufinden, wo sich Shu aufhält und wie wir dorthin gelangen können. In der Zwischenzeit könntet Ihr sicherlich von etwas Übung und Disziplin profitieren.\n\nEure erste Aufgabe wird diejenige sein, die allen Schülern, die sich in die Teiche begeben, zufällt: Findet einen Weg über die Balancierpfähle im Westen und läutet die Glocke, ohne in den Teich zu fallen.\n\nSolltet Ihr herunterfallen, wird der Fluch des Teichs es Euch erschweren, den Pfahl erneut zu erklimmen, sodass Ihr zum Ufer zurückkehren müsst, um von vorn zu beginnen.\n\nOh... und passt auf die Kraniche auf...", sourceObjective = "Findet einen Weg über die Balancierpfähle und läutet die Übungsglocke.", completion = "Gut. Ihr lernt schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[29662] = { id = 29662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Schilfrohre", description = "Besorgt mir etwas Schilfrohr von den Teichen ganz in der Nähe.\n\nFragt nicht warum. Tut es einfach, und lernt.", sourceObjective = "Sammelt 8 Stücke hartes Tränenholzschilf.", progress = "Euch meine Stärke zu schildern ist sinnlos. Ich muss sie Euch demonstrieren.", completion = "Gut.\n\nEs gibt kein einziges Schilfrohr, das meiner Kraft jemals widerstanden hätte.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29663] = { id = 29663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des balancierten Steines", description = "Ich benötige Ruhe, während ich meditiere. Übt Euch in Eurer Kampfkunst, während ich über Shus Aufenthaltsort nachsinne.\n\nAndere Mönche trainieren ihre Balance und Fähigkeiten im Kampf auf den Balancierpfählen in den umliegenden Teichen. Fordert sie heraus und besiegt sie.", sourceObjective = "Besiegt 6 Mönche der Tushui auf den Balancierpfählen.", completion = "Eure Fähigkeiten nehmen sichtlich zu. Euer Tritt wird sicherer. Eure Schläge sind kraftvoller.\n\nDisziplin und Übung sind die Schlüssel, um Euer Potenzial voll auszuschöpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29664] = { id = 29664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen des Herausforderers", description = "Ihr habt einen starken Geist und einen starken Willen, aber Euch fehlen die Fähigkeiten, um mir im Kampf gegenüberzutreten. Euer Körper muss den Kampf bestehen, aber in Wahrheit ist es Euer Charakter, der geprüft werden soll.\n\nLasst uns Chancengleichheit herstellen.\n\nNehmt diese Fackel, zündet sie im Kohlenbecken neben mir an und benutzt sie, um die drei erloschenen Kohlenbecken um den Teich herum anzuzünden.", sourceObjective = "Entzündet Eure unangezündete Herausfordererfackel am Kohlenbecken der flackernden Flamme und benutzt sie dann, um die 3 Kohlenbecken in der Nähe von Meister Li Fei anzuzünden.", completion = "Diese Feuer werden Euch die Stärke verleihen, die Ihr noch nicht erlangt habt. Sie werden Euer wahres Potenzial erhellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29665] = { id = 29665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen in die Traufe", description = "Nachdem ihr Schiff abgestürzt war, begannen finstere Kreaturen, aus dem Meer emporzusteigen und das Wrack zu durchforsten. Bei all dem Unglück, das ihnen heute widerfahren ist, wird unsere Hilfe womöglich nur ein Tropfen auf den heißen Stein sein.\n\nDennoch - diese Leute benötigen dringend unsere Hilfe. Bezwingt ihre Peiniger!", sourceObjective = "Bezwingt 8 Peiniger der Tiefenschuppen.", completion = "Ihr seid ein furchteinflößender Anblick auf dem Schlachtfeld!", sourceObjectiveStatus = "unverified-source-field" }
quests[29666] = { id = 29666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine knifflige Lektion", description = "In den Teichen lauern Gefahren. Die jüngste und wildeste davon sind die Wasserkneifer. Es ist an der Zeit, ihre Zahl auszudünnen, aber ich bin dazu nicht mehr imstande.\n\nFalls Ihr ein paar der Wasserkneifer beseitigen könntet, wäre ich Euch zu Dank verpflichtet. Passt aber auf ihre Anzahl auf - manchmal ist es besser, sie aus den Teichen herauszulocken, als geradewegs hineinzustapfen.", sourceObjective = "Tötet 6 Wasserkneifer.", completion = "Die Wasserkneifer sind merkwürdige Kreaturen. Es scheint sie zu stillen Gewässern hinzuziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29667] = { id = 29667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnung der Herde", description = "Anscheinend haben Kael'thas' Streitkräfte die Wesen der Botanika bis zur Unkenntlichkeit verändert. Ich will nicht, dass sie auf die Scherbenwelt losgelassen werden, wie so viele vor ihnen.\n\nEines dieser Wesen heißt Laj. Ihn würde ich gern untersuchen, denn er scheint irgendwie anders zu sein. Vielleicht können wir etwas von ihm lernen.", sourceObjective = "A'dal bittet Euch, 6 mutierte Fleischpeitscher, 6 mutierte Furchtkreischer und 6 mutierte Schrecken zu töten und einen schnellentwickelnden Wedel von Laj in der Botanika der Festung der Stürme zu erbeuten.", progress = "Wie ich sehe, habt Ihr den Wedel erbeutet. Sehr gut.", completion = "Ihr habt Euch tapfer geschlagen, {name}. Allerdings muss ich Euch noch um die Erfüllung einer letzten Aufgabe bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29669] = { id = 29669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst traurige Aufgabe", description = "Ich muss Euch leider mit einer äußerst traurigen Aufgabe betrauen.\n\nWarpzweig war einmal der Wächter der ganzen Botanika. Doch nun ist er unrein und muss beseitigt werden.", sourceObjective = "A'dal bittet Euch, Warpzweig in der Botanika in der Festung der Stürme zu töten.", completion = "Als er noch lebte, war er ein stattlicher Wächter. Wir werden ihn vermissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29670] = { id = 29670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Gormal", description = "Dank Euch versteckt sich eine aus Bauern bestehende Bürgerwehr in der Nähe. Hanae sagte etwas davon, ihnen \"flüssigen Mut\" zukommen zu lassen. Ich bin mir ziemlich sicher, dass sie jetzt betrunken und ZORNIG sind.\n\nDie Mogu glauben, sie könnten uns einfach überrollen - wir werden ihnen einen Kampf liefern, der ihnen die Augen öffnen wird.\n\nFolgt ihrer Spur durch die Ruinen und runter an den Strand. Findet ihren Anführer. Wenn Ihr ihn angreift, kommen wir dazu, um Euch zu helfen.", sourceObjective = "Tötet Unterwerfer Gormal im Lager Gormal.", completion = "Das ist äußerst beunruhigend. Wenn sich die Mogu so wie hier auf dem ganzen Kontinent zusammenschließen, würde dies eine ernste Bedrohung für Pandaria darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29671] = { id = 29671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Morast", description = "Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.\n\nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa'at.", sourceObjective = "Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa'at.", sourceObjectiveStatus = "unverified-source-field" }
quests[29672] = { id = 29672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Öffnung des Dunklen Portals", description = "Hier arbeitet Medivh verbissen an der Öffnung des Dunklen Portals.\n\nÜberall im Morast werden sich Zeitlöcher öffnen, aus denen die Ewigen herausströmen werden mit dem Ziel, Medivhs Schilde und schließlich auch Medivh selbst zu vernichten.\n\nTötet die Lords des Zeitlochs und ihre Anführer, bis Medivh erfolgreich war.", sourceObjective = "Sa'at im Schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat.\n\nKehrt zu Sa'at zurück, wenn Ihr erfolgreich wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[29673] = { id = 29673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Morast", description = "Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.\n\nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa'at.", sourceObjective = "Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa'at.", sourceObjectiveStatus = "unverified-source-field" }
quests[29674] = { id = 29674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbändige Dunkelheit", description = "<Ihr hört klagendes Geläut in Eurem Kopf.>\n\nWir haben die gefährlichsten Wesen, die uns auf unseren Reisen untergekommen sind, eingesperrt.\n\nZereketh ist ein mächtiger Leerenfürst. Wenn es ihm gelingt, in den Nethersturm zu entkommen, wird er die reichlich vorhandene Leerenenergie in sich aufsaugen.", sourceObjective = "A'dal hat Euch gebeten, Zereketh den Unabhängigen in der Arkatraz der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29675] = { id = 29675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn und Verdammnis", description = "Zornseher Soccothrates und Dalliah die Verdammnisverkünderin sind zwei mächtige Agenten der Brennenden Legion. Sie haben damit begonnen, Dämonen um sich zu versammeln.\n\nNoch ist die Armee klein, aber Ihr dürft nicht zulassen, dasss sie größer wird, sonst wird die Arkatraz bald zu einem weiteren Stützpunkt der Legion werden.", sourceObjective = "A'dal bittet Euch, Zornseher Soccothrates und Dalliah die Verdammnisverkünderin in der Arkatraz der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29676] = { id = 29676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen alten Freund finden", description = "Wie es scheint, hatte Shu, der Geist des Wassers, einen Spielgefährten, als er über die Jahre die Teiche besuchte. Es handelt sich um einen alten Pandaren, den wir den alten Liang nennen.\n\nLiang ist von der Hauptstadt fortgezogen und geht in den Teichen schon lange nicht mehr seinen Übungen nach. Man sagte mir, dass er in einem kleinen Haus nordöstlich von hier lebt, oben auf dem Hügel.\n\nLiang weiß vielleicht, was Shu vertrieben hat und wo wir den Geist finden könnten.\n\nGeht zu Liang und fragt nach Shu.", sourceObjective = "Sprecht mit dem alten Liang bei Liangs Refugium an den Singenden Teichen.", completion = "Besucher sind hier oben eine Seltenheit, aber Ihr seid willkommen. Es ist schön, Eure Bekanntschaft zu machen, junger {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29677] = { id = 29677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sonnenperle", description = "Shu, der Geist des Wassers, ist ewig jung, genau wie alle anderen Geister Shen-zin Sus. Ich bin mein ganzes Leben lang mit Shu befreundet gewesen, aber ich bin nicht mehr in der Lage, mit ihm zu spielen. Ich bin alt und habe schlicht keine Kraft mehr.\n\nBei all seiner Vielschichtigkeit ist Shu im Grunde einfach zufriedenzustellen: Er sehnt sich nach Freundschaft. Immer wenn ich zurückgekehrt bin, um mit Shu zu spielen, habe ich ihm eine Sonnenperle als Geschenk mitgebracht. Dann haben wir miteinander gespielt. In den Teichen im Südosten könnt Ihr eine Sonnenperle finden. Wer weiß, vielleicht werdet Ihr ja <sein neuer Freund/seine neue Freundin>...", sourceObjective = "Findet die Sonnenperle.", progress = "Die Entscheidung, nicht mehr zu den Teichen zurückzukehren, war eine schwere. Ich glaube, dass Shu sie nie wirklich verstanden hat. Er weiß nicht, wie es ist, alt und gebrechlich zu werden.", completion = "Shus Bedürfnisse sind den unseren nicht ganz unähnlich. Er möchte nicht allein sein - ungewollt, ungeliebt. Er sehnt sich danach, gebraucht zu werden und sein Leben mit anderen zu teilen.\n\nJetzt, wo Ihr dies wisst, sollte Euch klar sein, dass es nicht schwer sein sollte, sein Vertrauen zu gewinnen. Er sehnt sich einfach nur nach etwas Gesellschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29678] = { id = 29678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shu, der Geist des Wassers", description = "Shu, der Geist des Wassers, schmollt im tiefen Teich nördlich von hier vor sich hin. Überquert die Felsen und lasst dann die Sonnenperle in die Mitte des Teichs fallen. Er wird wissen, was das bedeutet.", sourceObjective = "Überredet Shu, den Geist des Wassers, zu einem Spielchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29679] = { id = 29679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Freund", description = "Er möchte, dass Ihr mit ihm spielt. Worauf wartet Ihr?", sourceObjective = "Wasserwandelt in 5 von Shus Wasserfontänen.", completion = "Ich muss schon zugeben, das sah von hier aus ziemlich lustig aus.\n\nUnd wie es aussieht, habt Ihr einen neuen Freund gewonnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29680] = { id = 29680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Lebensgrundlage", description = "Wir haben getan, was Meister Shang von uns verlangt hat. Ich werde zum Tempel zurückkehren und ihm von unserem Fortschritt berichten. Ihr solltet Euch nach Süden begeben, um Wugou, den Geist der Erde, aufzusuchen.\n\nJi erwartet Euch am Dai-Lo-Bauernhof und wird sicherlich Eure Hilfe benötigen. Ich muss Euch warnen - Ji kann in all seiner Direktheit sehr unbedacht agieren. Erinnert Euch stets an das, was ich Euch gelehrt habe: Disziplin und Geduld.", sourceObjective = "Sprecht mit Ji auf dem Dai-Lo-Bauernhof. Ein Karren wartet nahe der Straße, um Euch dorthin zu bringen.", completion = "{name}! Ich hatte mich gefragt, wann wir uns wohl wiedersehen würden.\n\nNun, die gute Nachricht ist, dass Wugou, der Geist der Erde, ziemlich einfach zu finden war. Die schlechte ist, dass er einen wirklich tiefen Schlaf hat. Er wird wohl mit einem ziemlich steifen Nacken aufwachen nach all dem Geschiebe und Getrete, mit dem ich ihn schon zu wecken versucht habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29681] = { id = 29681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Hochsicherheitstrakt", description = "Herold Horizontiss stellt das größte Problem in der Arkatraz dar.\n\nEr hat Aufseher Mellichar korrumpiert und dafür gesorgt, dass er zahlreiche Gefangene entlässt. Es ist nur eine Frage der Zeit, bis auch der Herold selbst freigelassen wird.\n\n{name}, Ihr dürft einen Diener der Alten Götter nicht am Leben lassen!", sourceObjective = "A'dal hat Euch gebeten, Herold Horizontiss in der Arkatraz der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29682] = { id = 29682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrasse der Magister", description = "Vor kurzem haben wir eine Expedition zur Terrasse der Magister geschickt, um die Streitkräfte der Legion aufzuhalten.\n\nAllerdings haben wir seitdem nichts mehr gehört, und ich befürchte das Schlimmste.\n\nWürdet Ihr dorthin gehen und versuchen, Exarch Larethor zu finden? Er leitet die Expedition.", sourceObjective = "Hauptmann Theris Morgenheim möchte, dass Ihr Exarch Larethor in der Terrasse der Magister findet.", completion = "Morgenheim hielt uns für tot? Ha!\n\nIch habe ihm keinen Bericht geschickt, weil wir noch nicht weiter als bis zu diesem Punkt gekommen sind.\n\nVielleicht können wir das ja mit Eurer Hilfe ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29683] = { id = 29683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seher der Seher", description = "<Tyrith stöhnt schmerzerfüllt auf, als er zu sprechen beginnt.>\n\nGeht zur Terrasse... benutzt die Kugel.\n\n... Sie nähren den Sonnenbrunnen...\n\n<Tyrith ringt nach Luft.>\n\nBeeilt Euch... Ihr müsst sie aufhalten... bevor sie...\n\n<Tyrith stirbt.>", sourceObjective = "Tyrith möchte, dass Ihr die Kugel auf dem Balkon in der Terrasse der Magister benutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29684] = { id = 29684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgerissene Kommunikation", description = "Wir haben vor einiger Zeit einen Kontaktmann in der Terrasse der Magister eingeschleust, der für uns Informationen sammelt, aber der Kontakt zu ihm ist abgerissen.\n\nSein Wissen ist für unsere Mission essentiell.", sourceObjective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr den Bluelfenspion Tyrith findet.", completion = "...kommt näher, {race}... Hört mir aufmerksam zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[29685] = { id = 29685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht totzukriegen", description = "Wie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Er muss aufgehalten werden.", sourceObjective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor in der Terrasse der Magister melden.", progress = "Nun ja, {class}, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.", completion = "<Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten in der Terrasse der Magister berichtet.>\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[29686] = { id = 29686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine radikale Idee", description = "Wir können es uns nicht leisten, diesen Krieg zu verlieren. Ich möchte unsere Wachen stärken, damit mutige Männer und Frauen nicht sterben müssen.\n\nDer Legion ist ein mächtiges Elementarwesen in die Klauen gefallen. Seine Essenz könnte genau das sein, was wir brauchen.", sourceObjective = "Exarch Larethor auf der Terrasse der Magister bittet Euch, Vexallus zu töten und seine Essenz an Euch zu bringen.", progress = "Habt Ihr seine Essenz bekommen?", completion = "Hervorragend! Ich freue mich darauf, dieses Projekt meinen Vorgesetzten zu zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29687] = { id = 29687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Allianzen", description = "Die Legion arbeitet immer enger mit Kael'thas' Streitkräften zusammen. Das bereitet mir große Sorgen.\n\nSoweit wir wissen, sind vor allem Selin Feuerherz und Priesterin Delrissa mit der Vereinigung der beiden Armeen beschäftigt. Ihr müsst sie aufhalten.", sourceObjective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr Selin Feuerherz und Priesterin Delrissa tötet.", completion = "Gut gemacht, Soldat. Ein Schritt nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29688] = { id = 29688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortführung der Kampagne", description = "Ich höre meistens zu, {class}. Ich höre zu, damit es der Kriegshäuptling nicht muss.\n\nIch habe gehört, wie es um unsere Kampagne gegen die Höllenfeuerzitadelle steht. Die Zeit zur Eroberung der Zerschmetterten Hallen, dem Machtzentrum der Höllenorcs, ist gekommen.\n\nSprecht mit Steingardist Stok'ton. Ihm unterstehen die Truppen dort.", sourceObjective = "Schattenjäger Ty'jin hat Euch gebeten, mit Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", completion = "Zieht den Kopf ein, sonst könnte er mit der falschen Seite eines Pfeils Bekanntschaft machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29689] = { id = 29689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortführung der Kampagne", description = "Die Zeit ist reif für einen letzten Schlag gegen die Höllenorcs.\n\nVorhutsspäher Chadwick erwartet Euch in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Beeilt Euch, ihre Streitkräfte können jeden Moment die Ehrenfeste angreifen!", sourceObjective = "Truppenkommandant Danath Trollbann hat Euch gebeten, mit Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", completion = "Seid still! Wenn sie uns jetzt bemerken, werden sie uns überrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29690] = { id = 29690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Nebel", description = "<Nazgrim füllt seine Lunge mit Seeluft.>\n\nRiecht Ihr das, {name}? Das ist der Geruch unserer Heimat; jenes Landes, für das unsere Leute geblutet und ihr Leben hingegeben haben.\n\nUnd horcht... Hört Ihr das? Das ist der Klang von Frieden und Sicherheit - von jener Zuflucht, die wir uns geschaffen haben und der sich unsere Feinde nicht zu nähern wagen.\n\nMerkt Euch diese Eindrücke, denn so bald werdet Ihr sie nicht wieder genießen. Es gilt, einen Krieg zu gewinnen.\n\nNun geht und macht Euch bereit. Wir brechen auf!", sourceObjective = "Sprecht mit General Nazgrim auf Höllschreis Faust.", completion = "{name}!?\n\nSie hatten mir berichtet, dass Ihr gefallen seid...\n\nEs freut mich zu sehen, dass dem nicht so war. Es gilt Allianztruppen zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[29691] = { id = 29691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein Gebüsch!", description = "Wir benutzen Bluthibiskus für viele Zwecke.\n\nNatürlich kommt er nur im Tiefensumpf vor und zahlreiche Bewohner haben Gefallen daran gefunden.\n\nIch wäre Euch sehr dankbar, wenn Ihr mir etwas davon bringen würdet.", sourceObjective = "Sammelt 5 Bluthibisken und kehrt zu T'shu im Tiefensumpf zurück.", progress = "Habt Ihr Hibiskus gefunden?", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?", sourceObjectiveStatus = "unverified-source-field" }
quests[29692] = { id = 29692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein weiteres Gebüsch!", progress = "Wir könnten noch mehr Bluthibiskus gebrauchen. Ständig sind wir auf der Suche danach.\n\nBringt sie mir in Fünferbündeln, dann werde ich mich erkenntlich zeigen.", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?" }
quests[29693] = { id = 29693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt des Generals", description = "Als Ihr langsam wieder zu Bewusstsein kommt und beginnt, Eure Umgebung wahrzunehmen, fällt Euch dieses Objekt unter den herumliegenden Wrackteilen auf.\n\nEuch dämmert, dass dies das erste Mal ist, dass Ihr Nazgrims Axt nicht in seinen Händen seht. Irgendwie macht das Eure knifflige Lage nur noch schlimmer...\n\nIhr wisst, dass der General seine Waffe wiederhaben wollen würde, sei er nun tot oder lebendig.", sourceObjective = "Bringt General Nazgrim seine Axt.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29694] = { id = 29694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu formieren!", description = "Sie haben eine Luftbasis! Diesen Allianzkapitän habe ich zum letzten Mal unterschätzt. So viele gute Krieger haben ihre Leben lassen müssen...\n\nEs muss ein paar Überlebende gegeben haben, die vor dem Absturz abspringen konnten. Wir brauchen alle fähigen Kämpfer, die wir bekommen können.\n\nFindet dort unten im Wald so viele Überlebende wie möglich, während ich das Wrack selbst durchsuche. Versammelt alle im nahegelegenen Dorf, damit wir zum Gegenschlag ausholen können.", sourceObjective = "Rettet Schattenmeisterin Kiryn, Nieti Kuppelplopp, Shokia und Unteroffizier Gorrok aus der Honigtaulichtung.", progress = "Habt Ihr Überlebende gefunden?", completion = "Das sind alle Überlebenden, {name}?\n\nSo sei es. Wir werden mit dem Blatt spielen, das das Schicksal uns zuteilt.\n\n\n\nVerdammt seien ihre Zahlen. So werden Helden gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29695] = { id = 29695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiryn-Verfolgung" }
quests[29696] = { id = 29696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Sterne!", description = "Einige von Kiryns Habseligkeiten wurden von Waldgeistern in der Gegend verteilt, aber dieser Gegenstand scheint Euch wichtig zu sein.\n\nDie Tasche hing einst an ihrer Taille und war gefüllt mit Wurfsternen. Ohne sie hat sie deutlich weniger Waffen zur Verfügung.\n\nWenn Ihr die Waffen von den Plagegeistern zurückholt, die in dieser Gegend hausen, würde Euch das sicherlich helfen.", sourceObjective = "Sammelt 100 von Kiryns Wurfsternen von verschlagenen Waldgeistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29697] = { id = 29697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieti-Verfolgen" }
quests[29698] = { id = 29698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Allianzbanner gefunden" }
quests[29699] = { id = 29699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Allianztruhe gefunden" }
quests[29700] = { id = 29700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Leibwächter gefunden" }
quests[29701] = { id = 29701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Tagebuch gefunden" }
quests[29702] = { id = 29702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorrok-VERFOLGUNG" }
quests[29703] = { id = 29703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fass voller Affen", description = "Diese Affenmenschen machen mich noch wahnsinnig! Ich will doch nur ein paar Einsichten in die pandarische Braukunst gewinnen, aber diese Ho-zen-Dinger trinken immer das ganze Bier weg, bevor ich dazu komme, einen chemischen Test durchzuführen. Könntet Ihr womöglich ein paar von ihnen auszuschalten? Das sollte den anderen eine Lehre sein - und für Euch sollte auch etwas dabei herausspringen...", sourceObjective = "Sally Zappenduster möchte, dass Ihr 5 betrunkene Affen tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29704] = { id = 29704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shokia VERFOLGEN" }
quests[29705] = { id = 29705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Flaschendiebe", description = "Als wenn die Ho-zen uns nicht schon genug Ärger bereitet hätten, lungern jetzt auch noch ein paar abtrünnige Möchtegern-Braumeister der Zwerge hier in der Gegend herum.\n\nKönntet Ihr bitte das Himmelsbräu wiederbeschaffen, das sie gestohlen haben? Es würde der Marktwirtschaft in Eisenschmiede erheblichen Schaden zufügen, wenn plötzlich so viele neue \"Unternehmer\" auftauchen.", sourceObjective = "Sally Zappenduster möchte, dass Ihr 5 Flaschen gestohlenes Himmelsbräu von den Jägern des vergorenen Schatzes in der Nähe des Bauernhofs auf Shen-zin Su zurückerobert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29706] = { id = 29706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'zapft is!", description = "Oh nein! Die Geistwandler in der Nähe sind in Wut verfallen - das ist doch reine Wettbewerbsverzerrung!\n\nKümmert Euch um sie, bevor sie unsere Gesichter verspeisen!", sourceObjective = "Tötet 5 wütende Geistwandler, bevor sie das Gesicht von Sally Zappenduster verspeisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29707] = { id = 29707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Gesprengte Ketten 1" }
